/**
 * 2.3 (12.11.2026) — Darslar for every teacher.
 *  - groups live in _p_groups (subject, Telegram chat); a new group sheet is built with all gradebook formulas;
 *  - students: add a list, rename, remove (row archived in _p_archive first), restore;
 *  - a lesson date can be moved (journal header + lesson topic + quiz date move together);
 *  - Telegram group chats are noticed by the bot when it is added to a group;
 *  - first install from the sheet menu and "Update platform" (Apps Script API) for colleagues' copies.
 */

/* ---------- groups ---------- */

/** _p_groups rows by group name (cached). Empty table = old setup: groups are the 3-digit sheets. */
function groupsMeta_() {
  const out = {};
  try { readTableC_('_p_groups').forEach(function (r) { if (r.group) out[r.group] = r; }); } catch (e) { /* first run */ }
  return out;
}
function subjectOf_(g) { const m = groupsMeta_()[String(g)]; return (m && m.subject) || (typeof SUBJECTS !== 'undefined' && SUBJECTS[g]) || ''; }
function chatOf_(g) { const m = groupsMeta_()[String(g)]; return (m && m.chat_id) || (typeof GROUP_CHATS !== 'undefined' && GROUP_CHATS[g]) || ''; }
function subjectsMap_() { const o = {}; listGroups_().forEach(function (g) { o[g] = subjectOf_(g); }); return o; }

/** Old setups (Valisher's) get their _p_groups rows once, from the 3-digit sheets and the old constants. */
function seedGroups_() {
  if (readTableC_('_p_groups').length) return;
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    if (readTable_('_p_groups').length) return;
    ss_().getSheets().map(function (s) { return s.getName(); }).filter(function (n) { return /^\d{3}$/.test(n); }).forEach(function (g) {
      upsertRow_('_p_groups', function () { return false; }, { group: g, subject: (typeof SUBJECTS !== 'undefined' && SUBJECTS[g]) || '',
        chat_id: (typeof GROUP_CHATS !== 'undefined' && GROUP_CHATS[g]) || '', chat_title: '', status: 'active', created_at: nowStr_() });
    });
  } finally { lock.releaseLock(); }
}

function nowStr_() { return Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyyy-MM-dd HH:mm'); }
function cleanName_(s) { return String(s == null ? '' : s).replace(/[​-‍﻿]/g, '').replace(/\s+/g, ' ').trim(); }
function validGroupName_(g) {
  g = cleanName_(g);
  if (!g) throw new Error('Write the group name (for example 101 or 2-23).');
  if (g.length > 20) throw new Error('The group name is too long (20 characters at most).');
  if (/^_/.test(g) || /^TEST$/i.test(g)) throw new Error('This name is reserved. Choose another one.');
  if (/[\[\]\*\?\/\\:']/.test(g)) throw new Error('Do not use these characters in a group name: [ ] * ? / \\ : \'');
  return g;
}

/** Everything the Groups page shows. */
function apiGroupsAdmin(t) {
  requireTeacher_(t);
  seedGroups_();
  const meta = groupsMeta_(), sheets = ss_().getSheets().map(function (s) { return s.getName(); });
  const accs = readTableC_('_p_students');
  const arch = readTableC_('_p_archive').filter(function (r) { return r.status === 'archived'; });
  const list = Object.keys(meta).filter(function (g) { return sheets.indexOf(g) >= 0; }).map(function (g) {
    const m = meta[g];
    let d = null; try { d = readGroup_(g, false); } catch (e) { d = null; }
    const days = d ? d.cols.filter(function (c) { return c.kind === 'day'; }) : [];
    return { group: g, subject: m.subject || '', chat_id: m.chat_id || '', chat_title: m.chat_title || '', status: m.status || 'active',
      students: d ? d.students.length : 0, lessons: days.length, first: days.length ? days[0].h : '', last: days.length ? days[days.length - 1].h : '',
      linked: accs.filter(function (a) { return a.group === g && a.status === 'active'; }).length,
      archived: arch.filter(function (a) { return a.group === g; }).length };
  });
  return { groups: list, chats: knownChats_(), botUsername: props_().getProperty('BOT_USERNAME') || '',
    groupBotUsername: props_().getProperty('GROUP_BOT_USERNAME') || '', main: IS_MAIN };
}

/** One group: students (with Telegram state), lesson dates, archived students. */
function apiGroupInfo(t, g) {
  requireTeacher_(t);
  g = String(g);
  const d = readGroup_(g, true);
  const accs = readTable_('_p_students').filter(function (a) { return a.group === g && (a.status === 'active' || a.status === 'pending'); });
  return {
    group: g, subject: subjectOf_(g), chat_id: chatOf_(g),
    students: d.students.map(function (s) {
      const a = accs.filter(function (x) { return x.full_name === s.name; })[0];
      return { row: s.row, name: s.name, tg: a ? a.status : '' };
    }),
    days: d.cols.filter(function (c) { return c.kind === 'day'; }).map(function (c) { return { col: c.c, date: c.h, block: c.block }; }),
    archive: readTable_('_p_archive').filter(function (r) { return r.group === g && r.status === 'archived'; })
      .map(function (r) { return { id: r.id, name: r.full_name, at: r.removed_at }; })
  };
}

function apiUpdateGroup(t, g, patch) {
  requireTeacher_(t);
  g = String(g); patch = patch || {};
  seedGroups_();
  if (!groupsMeta_()[g]) throw new Error('Unknown group: ' + g);
  const o = { group: g };
  if (patch.subject != null) o.subject = cleanName_(patch.subject).slice(0, 80);
  if (patch.chat_id != null) {
    const c = String(patch.chat_id).trim();
    if (c && !/^-?\d{5,20}$/.test(c)) throw new Error('A Telegram chat id is a number like -1001234567890.');
    o.chat_id = c;
    const known = knownChats_().filter(function (x) { return x.id === c; })[0];
    o.chat_title = known ? known.title : '';
  }
  if (patch.status != null) o.status = patch.status === 'archived' ? 'archived' : 'active';
  upsertRow_('_p_groups', function (r) { return r.group === g; }, o);
  log_('teacher', 'group-edit', g + ' ' + JSON.stringify(patch));
  return apiGroupsAdmin(t);
}

/**
 * New group sheet with the same structure and formulas as the existing gradebooks.
 * o = { group, subject, title, dates1:['dd.mm.yyyy'], dates2:[...], mi:'pw'|'mt'|'none', students:[names], topics:[...] }
 */
function apiCreateGroup(t, o) {
  requireTeacher_(t);
  o = o || {};
  const g = validGroupName_(o.group);
  const ss = ss_();
  if (ss.getSheetByName(g)) throw new Error('A sheet called "' + g + '" already exists.');
  const d1 = (o.dates1 || []).map(parseFullDate_), d2 = (o.dates2 || []).map(parseFullDate_);
  if (!d1.length) throw new Error('Block 1 needs at least one lesson date.');
  if (d1.length + d2.length > 120) throw new Error('Too many lesson dates (120 at most).');
  const all = d1.concat(d2).map(function (x) { return x.key; });
  if (all.some(function (k, i) { return all.indexOf(k) !== i; })) throw new Error('The same date appears twice.');
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    seedGroups_();
    const sh = ss.insertSheet(g);
    buildGroupSheet_(sh, { title: o.title || (g + ' guruhi. Baholash jurnali'), d1: d1, d2: d2, mi: o.mi || 'pw', mt: Number(o.mtCount) || 10 });
    upsertRow_('_p_groups', function (r) { return r.group === g; }, { group: g, subject: cleanName_(o.subject).slice(0, 80), chat_id: '', chat_title: '', status: 'active', created_at: nowStr_() });
    clearGroupCache_(g);
    log_('teacher', 'group-new', g + ' | ' + d1.length + '+' + d2.length + ' lessons | ' + (o.mi || 'pw'));
  } finally { lock.releaseLock(); }
  const names = (o.students || []).map(cleanName_).filter(String);
  if (names.length) addStudents_(g, names);
  const topics = (o.topics || []).map(cleanName_);
  if (topics.some(String)) {
    const dates = d1.concat(d2);
    topics.slice(0, dates.length).forEach(function (tp, i) {
      if (!tp) return;
      const m = /^(.{1,20}?)\s+[-–—:]\s+(.+)$/.exec(tp);
      upsertRow_('_p_lessons', function (r) { return r.group === g && r.date === dates[i].ddmm; },
        { group: g, date: dates[i].ddmm, unit: m ? m[1] : '', topic: m ? m[2] : tp });
    });
  }
  return { group: g, groups: listGroups_() };
}

function parseFullDate_(s) {
  const m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(String(s || '').trim());
  if (!m) throw new Error('Date "' + s + '" must look like 14.09.2026.');
  const d = +m[1], mo = +m[2], y = +m[3];
  const dt = new Date(y, mo - 1, d);
  if (dt.getMonth() !== mo - 1 || dt.getDate() !== d) throw new Error('Date "' + s + '" does not exist.');
  return { d: d, m: mo, y: y, ddmm: ('0' + d).slice(-2) + '.' + ('0' + mo).slice(-2), key: y * 10000 + mo * 100 + d };
}

function colA1_(n) { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; }

function buildGroupSheet_(sh, o) {
  const H = ['№', 'F.I.Sh.'], S = [], dates = [];   // headers, sections [first col, text, span]
  const sec = function (text, span) { S.push([H.length + 1, text, span]); };
  sec('1-blok: kunlik baholar (0 dan 10 gacha, kelmasa 0)', o.d1.length);
  o.d1.forEach(function (x) { dates.push([H.length + 1, x]); H.push(x.ddmm); });
  sec('1-reyting (HEMIS)', 4); H.push('Joriy (jami)', 'Joriy (20)', 'Oraliq N (20)', '1-reyting (20)');
  if (o.d2.length) {
    sec('2-blok: kunlik baholar (0 dan 10 gacha, kelmasa 0)', o.d2.length);
    o.d2.forEach(function (x) { dates.push([H.length + 1, x]); H.push(x.ddmm); });
    sec('2-reyting', 4); H.push('Joriy (jami)', 'Joriy (20)', 'Oraliq N (20)', '2-reyting (20)');
  }
  if (o.mi === 'mt') {
    const n = Math.max(1, Math.min(20, o.mt || 10));
    sec("Mustaqil ta'lim (10 ball)", n + 1);
    for (let i = 1; i <= n; i++) H.push('MT' + i + ' (1)');
    H.push('MI (10)');
  } else if (o.mi === 'pw') {
    sec("Mustaqil ta'lim (10 ball)", 5); H.push('PW1 jamoasi', 'PW1 (5)', 'PW2 jamoasi', 'PW2 (5)', 'MI (10)');
  }
  sec('Natija', 5); H.push('ON (30)', 'Yakuniygacha (50)', 'YN (50)', 'Jami (100)', 'NB soni');
  const n = H.length;
  if (sh.getMaxColumns() < n) sh.insertColumnsAfter(sh.getMaxColumns(), n - sh.getMaxColumns());
  if (sh.getMaxColumns() > n) sh.deleteColumns(n + 1, sh.getMaxColumns() - n);
  if (sh.getMaxRows() > 120) sh.deleteRows(121, sh.getMaxRows() - 120);
  sh.getRange(1, 1).setValue(o.title).setFontWeight('bold').setFontSize(12);
  S.forEach(function (s) {
    const r = sh.getRange(2, s[0], 1, s[2]);
    if (s[2] > 1) r.merge();
    r.setValue(s[1]).setHorizontalAlignment('center').setFontWeight('bold').setWrap(true);
  });
  sh.getRange(3, 1, 1, n).setValues([H]).setFontWeight('bold').setWrap(true).setVerticalAlignment('middle').setHorizontalAlignment('center');
  dates.forEach(function (x) { sh.getRange(3, x[0]).setFormula('=DATE(' + x[1].y + ',' + x[1].m + ',' + x[1].d + ')').setNumberFormat('dd.mm'); });
  sh.setFrozenRows(3); sh.setFrozenColumns(2);
  sh.setColumnWidth(1, 34); sh.setColumnWidth(2, 260);
  sh.setColumnWidths(3, n - 2, 56);
  sh.getRange(1, 1, 3, n).setBackground('#f1f5f2');
  sh.getRange(4, 1, sh.getMaxRows() - 3, n).setFontWeight('normal').setHorizontalAlignment('center');
  sh.getRange(4, 2, sh.getMaxRows() - 3, 1).setHorizontalAlignment('left');
  // formula columns are grey, like the existing gradebooks
  const fcols = formulaCols_(H);
  Object.keys(fcols).forEach(function (c) { if (c !== '1') sh.getRange(3, Number(c), sh.getMaxRows() - 2, 1).setBackground('#e8e8e8'); });
  SpreadsheetApp.flush();
}

/**
 * Gradebook formulas for one student row, built from the header names (row 3).
 * Returns {colNumber: 'A1 formula'} — same formulas as the gradebooks made by hand.
 */
function formulaCols_(H, r) {
  r = r || 4;
  const out = {}, find = function (name, from) { for (let i = from || 0; i < H.length; i++) if (H[i] === name) return i + 1; return 0; };
  const isDate = function (h) { return /^\d{2}\.\d{2}$/.test(h); };
  const blocks = [];
  let i = 0;
  while (i < H.length) {
    if (isDate(H[i])) { const a = i + 1; while (i < H.length && isDate(H[i])) i++; blocks.push({ a: a, b: i }); } else i++;
  }
  const ref = function (c) { return colA1_(c) + r; };
  out[1] = '=ROW()-3';
  const ratings = [], nb = [];
  blocks.slice(0, 2).forEach(function (bl, k) {
    const rng = colA1_(bl.a) + r + ':' + colA1_(bl.b) + r;
    nb.push('COUNTIF(' + rng + ',"nb")+COUNTIF(' + rng + ',0)');
    const j = find('Joriy (jami)', bl.b), j20 = find('Joriy (20)', bl.b), on = find('Oraliq N (20)', bl.b), rt = find((k + 1) + '-reyting (20)', bl.b);
    if (j) out[j] = '=SUM(' + rng + ')';
    if (j && j20) out[j20] = '=' + ref(j) + '*20/(10*COLUMNS(' + rng + '))';
    if (rt && j20 && on) { out[rt] = '=(' + ref(j20) + '+' + ref(on) + ')/2'; ratings.push(rt); }
  });
  const parts = [];
  H.forEach(function (h, idx) { if (/^PW[12] \(5\)$/.test(h) || /^MT\d+ \(1\)$/.test(h)) parts.push(idx + 1); });
  const mi = find('MI (10)'), onx = find('ON (30)'), yk = find('Yakuniygacha (50)'), yn = find('YN (50)'), jami = find('Jami (100)'), nbc = find('NB soni');
  if (mi && parts.length) out[mi] = '=' + parts.map(ref).join('+');
  if (onx) out[onx] = '=' + [ratings[1], mi].filter(Boolean).map(ref).join('+');
  if (yk && onx) out[yk] = '=' + [ratings[0], onx].filter(Boolean).map(ref).join('+');
  if (jami && yk && yn) out[jami] = '=' + ref(yk) + '+' + ref(yn);
  if (nbc && nb.length) out[nbc] = '=' + nb.map(function (x) { return '(' + x + ')'; }).join('+');
  Object.keys(out).forEach(function (k) { if (out[k] === '=') delete out[k]; });
  return out;
}

/* ---------- students ---------- */

function apiAddStudents(t, g, names) {
  requireTeacher_(t);
  const list = (Array.isArray(names) ? names : String(names || '').split(/\r?\n/)).map(cleanName_).filter(String);
  if (!list.length) throw new Error('Write at least one name (one name per line).');
  addStudents_(String(g), list);
  return apiGroupInfo(t, g);
}

/** Appends students after the last one; formulas copied from the row above (or built from the headers). */
function addStudents_(g, names) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const d = readGroup_(g, true), sh = groupSheet_(g);
    const have = {}; d.students.forEach(function (s) { have[s.name.toLowerCase()] = 1; });
    const seen = {};
    names.forEach(function (n) {
      if (n.length > 90) throw new Error('Name is too long: ' + n.slice(0, 40) + '…');
      const k = n.toLowerCase();
      if (have[k]) throw new Error(n + ' is already in group ' + g + '.');
      if (seen[k]) throw new Error(n + ' is written twice.');
      seen[k] = 1;
    });
    const lc = sh.getLastColumn();
    const lastRow = d.students.length ? d.students[d.students.length - 1].row : HEADER_ROW;
    // an empty group (new sheet) is written in place; otherwise new rows go right after the last student
    if (d.students.length || sh.getLastRow() > HEADER_ROW) sh.insertRowsAfter(lastRow, names.length);
    else if (sh.getMaxRows() < HEADER_ROW + names.length + 1) sh.insertRowsAfter(sh.getMaxRows(), names.length + 1);
    const first = lastRow + 1;
    let rowF;
    if (d.students.length) {
      rowF = sh.getRange(lastRow, 1, 1, lc).getFormulasR1C1()[0];
    } else {
      const H = sh.getRange(HEADER_ROW, 1, 1, lc).getDisplayValues()[0].map(function (h) { return String(h).trim(); });
      const f = formulaCols_(H, first);
      rowF = H.map(function (h, i) { return f[i + 1] ? a1ToR1C1_(f[i + 1], first) : ''; });
    }
    sh.getRange(first, 1, names.length, lc).clearContent();
    // one call per formula column (an empty string in setFormulasR1C1 would leave #ERROR! in plain cells)
    rowF.forEach(function (f, i) { if (f) sh.getRange(first, i + 1, names.length, 1).setFormulaR1C1(f); });
    sh.getRange(first, NAME_COL, names.length, 1).setValues(names.map(function (n) { return [n]; }));
    SpreadsheetApp.flush();
    clearGroupCache_(g);
    log_('teacher', 'student-add', g + ' | ' + names.join(', '));
  } finally { lock.releaseLock(); }
}

/** Turns "=SUM(C4:Q4)" written for row r into relative R1C1 (same row). Only plain column+row refs. */
function a1ToR1C1_(f, r) {
  return f.replace(/\b([A-Z]{1,3})(\d+)\b/g, function (all, col, row) {
    let c = 0; for (let i = 0; i < col.length; i++) c = c * 26 + (col.charCodeAt(i) - 64);
    const dr = Number(row) - r;
    return 'R' + (dr ? '[' + dr + ']' : '') + 'C' + c;
  });
}

function studentAt_(g, row, name) {
  const d = readGroup_(g, true);
  const st = d.students.filter(function (s) { return s.row === Number(row); })[0];
  if (!st || (name != null && st.name !== name)) throw new Error('The list has changed. Open it again and retry.');
  return { d: d, st: st };
}

const NAME_TABLES = ['_p_students', '_p_attempts', '_p_personal', '_p_outbox'];

function apiRenameStudent(t, g, row, oldName, newName) {
  requireTeacher_(t);
  g = String(g); newName = cleanName_(newName);
  if (!newName) throw new Error('Write the new name.');
  if (newName.length > 90) throw new Error('The name is too long.');
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const x = studentAt_(g, row, oldName);
    if (x.d.students.some(function (s) { return s.row !== x.st.row && s.name.toLowerCase() === newName.toLowerCase(); })) throw new Error(newName + ' is already in this group.');
    groupSheet_(g).getRange(x.st.row, NAME_COL).setValue(newName);
    NAME_TABLES.forEach(function (tb) {
      const sh = pSheet_(tb), head = P_SHEETS[tb], gi = head.indexOf('group'), ni = head.indexOf('full_name');
      const vals = sh.getDataRange().getValues();
      let n = 0;
      for (let i = 1; i < vals.length; i++) if (String(vals[i][gi]) === g && String(vals[i][ni]) === oldName) { sh.getRange(i + 1, ni + 1).setValue(newName); n++; }
      if (n) tableChanged_(tb);
    });
    SpreadsheetApp.flush(); clearGroupCache_(g);
    log_('teacher', 'student-rename', g + ' | ' + oldName + ' -> ' + newName);
  } finally { lock.releaseLock(); }
  return apiGroupInfo(t, g);
}

/** The row (values + formulas) goes to _p_archive first, then it is deleted from the gradebook. */
function apiRemoveStudent(t, g, row, name) {
  requireTeacher_(t);
  g = String(g);
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const x = studentAt_(g, row, name), sh = groupSheet_(g), lc = sh.getLastColumn();
    const rg = sh.getRange(x.st.row, 1, 1, lc);
    const H = sh.getRange(HEADER_ROW, 1, 1, lc).getDisplayValues()[0];
    const keep = { h: H, v: rg.getValues()[0].map(function (v) { return v instanceof Date ? v.toISOString() : v; }), f: rg.getFormulasR1C1()[0] };
    const id = 'a' + newToken_().slice(0, 10);
    upsertRow_('_p_archive', function () { return false; }, { id: id, group: g, full_name: x.st.name, removed_at: nowStr_(), data_json: JSON.stringify(keep), status: 'archived' });
    readTable_('_p_students').filter(function (a) { return a.group === g && a.full_name === x.st.name && (a.status === 'active' || a.status === 'pending'); })
      .forEach(function (a) {
        if (a.token) CacheService.getScriptCache().remove('stu_' + a.token);
        patchRowAt_('_p_students', a, { status: 'removed', token: '' });
      });
    sh.deleteRow(x.st.row);
    SpreadsheetApp.flush(); clearGroupCache_(g);
    log_('teacher', 'student-remove', g + ' | ' + x.st.name + ' | archive ' + id);
  } finally { lock.releaseLock(); }
  return apiGroupInfo(t, g);
}

/** Puts an archived student back at the end of the group: marks are matched by column name. */
function apiRestoreStudent(t, id) {
  requireTeacher_(t);
  const a = readTable_('_p_archive').filter(function (r) { return r.id === String(id) && r.status === 'archived'; })[0];
  if (!a) throw new Error('This archived student was not found (maybe already restored).');
  const g = a.group;
  if (!ss_().getSheetByName(g)) throw new Error('Group ' + g + ' no longer exists.');
  const keep = JSON.parse(a.data_json || '{}');
  addStudents_(g, [a.full_name]);
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const d = readGroup_(g, true), sh = groupSheet_(g);
    const st = d.students.filter(function (s) { return s.name === a.full_name; })[0];
    const used = {};
    d.cols.forEach(function (c) {
      if (['day', 'manual', 'team'].indexOf(c.kind) < 0) return;
      const k = (keep.h || []).indexOf(c.h, used[c.h] || 0);   // same header twice (two blocks): take them in order
      if (k < 0) return;
      used[c.h] = k + 1;
      const v = keep.v[k], f = keep.f && keep.f[k];
      if (f || v === '' || v == null) return;
      sh.getRange(st.row, c.c).setValue(v);
    });
    patchRowAt_('_p_archive', a, { status: 'restored' });
    SpreadsheetApp.flush(); clearGroupCache_(g);
    log_('teacher', 'student-restore', g + ' | ' + a.full_name);
  } finally { lock.releaseLock(); }
  return apiGroupInfo(t, g);
}

/* ---------- lesson dates ---------- */

/** Moves one lesson to another day: the header date, the saved topic and the quiz date move together. */
function apiMoveLesson(t, g, col, oldDate, newDate) {
  requireTeacher_(t);
  g = String(g);
  const nd = parseFullDate_(newDate);
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const d = readGroup_(g, true);
    const c = d.cols[Number(col) - 1];
    if (!c || c.kind !== 'day' || c.h !== oldDate) throw new Error('The dates have changed. Open the list again.');
    if (nd.ddmm === oldDate) return apiGroupInfo(t, g);
    if (d.cols.some(function (x) { return x.kind === 'day' && x.h === nd.ddmm; })) throw new Error('Group ' + g + ' already has a lesson on ' + nd.ddmm + '.');
    groupSheet_(g).getRange(HEADER_ROW, c.c).setFormula('=DATE(' + nd.y + ',' + nd.m + ',' + nd.d + ')').setNumberFormat('dd.mm');
    readTable_('_p_lessons').filter(function (r) { return r.group === g && r.date === oldDate; })
      .forEach(function (r) { patchRowAt_('_p_lessons', r, { date: nd.ddmm }); });
    readTable_('_p_quizzes').filter(function (r) { return r.group === g && r.lesson_date === oldDate && r.status !== 'closed'; })
      .forEach(function (r) { patchRowAt_('_p_quizzes', r, { lesson_date: nd.ddmm }); });
    SpreadsheetApp.flush(); clearGroupCache_(g);
    log_('teacher', 'lesson-move', g + ' | ' + oldDate + ' -> ' + nd.ddmm);
  } finally { lock.releaseLock(); }
  return apiGroupInfo(t, g);
}

/* ---------- Telegram group chats seen by the bot ---------- */

function knownChats_() {
  let m = {};
  try { m = JSON.parse(getSetting_('tg_chats', '{}') || '{}'); } catch (e) { m = {}; }
  return Object.keys(m).map(function (id) { return { id: id, title: m[id].title || '', at: m[id].at || '', left: !!m[id].left }; })
    .sort(function (a, b) { return String(b.at).localeCompare(String(a.at)); });
}
function noteChat_(chat, left) {
  if (!chat || (chat.type !== 'group' && chat.type !== 'supergroup')) return;
  let m = {};
  try { m = JSON.parse(getSetting_('tg_chats', '{}') || '{}'); } catch (e) { m = {}; }
  const id = String(chat.id), old = m[id] || {};
  if (old.title === (chat.title || '') && !!old.left === !!left) return;
  m[id] = { title: chat.title || '', at: nowStr_(), left: left ? 1 : 0 };
  setSetting_('tg_chats', JSON.stringify(m));
}
/** A group became a supergroup: Telegram gives it a new id. */
function migrateChat_(oldId, newId, title) {
  noteChat_({ id: newId, type: 'supergroup', title: title });
  readTable_('_p_groups').filter(function (r) { return r.chat_id === String(oldId); })
    .forEach(function (r) { patchRowAt_('_p_groups', r, { chat_id: String(newId) }); });
}

