  const pick = function (k) { const m = new RegExp(k + '["\']?\\s*:\\s*["\']([^"\']+)["\']').exec(text); return m ? m[1] : ''; };
  const cfg = { apiKey: pick('apiKey'), authDomain: pick('authDomain'), databaseURL: pick('databaseURL'), projectId: pick('projectId'), appId: pick('appId') };
  if (!cfg.apiKey || !cfg.projectId || !cfg.appId) throw new Error('Paste the whole firebaseConfig block (apiKey, projectId, appId…).');
