/* ---------- install (sheet menu) and self-update (Apps Script API) ---------- */

const BUNDLE_URL = 'https://valisher111.github.io/darslar/backend/';

function gasApi_(method, path, body) {
  const o = { method: method, muteHttpExceptions: true, headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() } };
  if (body) { o.contentType = 'application/json'; o.payload = JSON.stringify(body); }
  const res = UrlFetchApp.fetch('https://script.googleapis.com/v1/projects/' + ScriptApp.getScriptId() + path, o);
  const code = res.getResponseCode(), txt = res.getContentText();
  if (code >= 300) {
    if (/usersettings|has not enabled|not been used|is disabled/i.test(txt)) throw new Error('APPS_SCRIPT_API_OFF');
    throw new Error('Apps Script API ' + code + ': ' + txt.slice(0, 300));
  }
  return txt ? JSON.parse(txt) : {};
}

function webappId_() { return props_().getProperty('WEBAPP_ID') || (IS_MAIN ? MAIN_DEPLOYMENT : ''); }
function siteLink_(withSetup) {
  const id = webappId_();
  const parts = [];
  if (id && id !== MAIN_DEPLOYMENT) parts.push('api=' + id);
  if (withSetup) parts.push('setup=' + getTeacherToken_());
  return SITE_URL + (parts.length ? '#' + parts.join('&') : '');
}

/** Sheet menu → Darslar → Install / open. Safe to run again. */
function installDarslar() {
  const P = props_(), ssId = SpreadsheetApp.getActiveSpreadsheet().getId();
  // a copy of somebody's installed sheet carries their settings: start clean
  if (!IS_MAIN && P.getProperty('INSTALLED_FOR') && P.getProperty('INSTALLED_FOR') !== ssId) P.deleteAllProperties();
  P.setProperty('INSTALLED_FOR', ssId);
  ensureSheets_();
  ensureTrigger_();
  if (!webappId_()) {
    try {
      const v = gasApi_('post', '/versions', { description: 'Darslar ' + APP_BUILD });
      const d = gasApi_('post', '/deployments', { versionNumber: v.versionNumber, manifestFileName: 'appsscript', description: 'Darslar (do not delete)' });
      P.setProperty('WEBAPP_ID', d.deploymentId);
      P.setProperty('WEBAPP_VER', String(v.versionNumber));
    } catch (e) {
      if (e.message !== 'APPS_SCRIPT_API_OFF') throw e;
      return showDialog_('One more step',
        '<p>Google needs your permission for Darslar to publish itself.</p><ol>' +
        '<li>Open <a href="https://script.google.com/home/usersettings" target="_blank">script.google.com/home/usersettings</a></li>' +
        '<li>Turn <b>Google Apps Script API</b> to <b>On</b>.</li>' +
        '<li>Come back and press <b>Darslar → Install / open</b> again.</li></ol>');
    }
  }
  log_('teacher', 'install', webappId_());
  const first = !P.getProperty('PW_HASH');
  showDialog_(first ? 'Darslar is installed' : 'Darslar',
    (first ? '<p>Open the site and create your password. Keep this link private until you set the password.</p>'
           : '<p>Your Darslar site (sign in with your password):</p>') +
    '<p><a class="b" href="' + siteLink_(first) + '" target="_blank">Open Darslar</a></p>' +
    '<p style="color:#666;font-size:12px">Bookmark the site after you sign in. You can always open it again from this menu.</p>');
}

function showDialog_(title, html) {
  const page = '<div style="font:14px/1.5 system-ui,Arial;color:#222">' + html + '</div>' +
    '<style>a.b{display:inline-block;background:#0f766e;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none;font-weight:600}</style>';
  SpreadsheetApp.getUi().showModalDialog(HtmlService.createHtmlOutput(page).setWidth(460).setHeight(260), title);
}

function cmpBuild_(a, b) {
  const x = String(a).split('.').map(Number), y = String(b).split('.').map(Number);
  for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d > 0 ? 1 : -1; }
  return 0;
}
function latest_() {
  const res = UrlFetchApp.fetch(BUNDLE_URL + 'version.json?t=' + Date.now(), { muteHttpExceptions: true });
  if (res.getResponseCode() !== 200) throw new Error('Could not check for updates now. Try later.');
  return JSON.parse(res.getContentText());
}
function apiCheckUpdate(t) {
  requireTeacher_(t);
  if (IS_MAIN) return { build: APP_BUILD, latest: APP_BUILD, main: true };
  const v = latest_();
  return { build: APP_BUILD, latest: v.build, notes: v.notes || '', newer: cmpBuild_(v.build, APP_BUILD) > 0 };
}
/** Copies the newest code into this teacher's script and points the site at it. Data is not touched. */
function apiUpdatePlatform(t) {
  requireTeacher_(t);
  if (IS_MAIN) throw new Error('This is the main copy: it is updated by Valisher.');
  const id = webappId_();
  if (!id) throw new Error('Run Darslar → Install / open in the sheet first.');
  const v = latest_();
  if (cmpBuild_(v.build, APP_BUILD) <= 0) return { build: APP_BUILD, upToDate: true };
  const res = UrlFetchApp.fetch(BUNDLE_URL + 'bundle-' + v.build + '.json', { muteHttpExceptions: true });
  if (res.getResponseCode() !== 200) throw new Error('The update file is not ready yet. Try later.');
  const b = JSON.parse(res.getContentText());
  if (!b.files || !b.files.some(function (f) { return f.name === 'appsscript'; })) throw new Error('The update file is broken. Tell Valisher.');
  try {
    gasApi_('put', '/content', { files: b.files });
    const ver = gasApi_('post', '/versions', { description: 'Darslar ' + v.build });
    props_().setProperty('WEBAPP_PREV', props_().getProperty('WEBAPP_VER') || '');
    gasApi_('put', '/deployments/' + id, { deploymentConfig: { versionNumber: ver.versionNumber, manifestFileName: 'appsscript', description: 'Darslar ' + v.build } });
    props_().setProperty('WEBAPP_VER', String(ver.versionNumber));
  } catch (e) {
    if (e.message === 'APPS_SCRIPT_API_OFF') throw new Error('Turn on "Google Apps Script API" at script.google.com/home/usersettings, then press Update again.');
    throw e;
  }
  log_('teacher', 'update', APP_BUILD + ' -> ' + v.build);
  return { build: v.build, updated: true };
}

