/* ---------- Lessons ---------- */

function apiLessons(t, g) {
  requireTeacher_(t);
  try { seedLessons_(); } catch (e) { log_('system', 'lessons-seed-error', String(e)); }
  g = String(g);
  const data = readGroup_(g, false);
  const today = Utilities.formatDate(new Date(), 'Asia/Tashkent', 'dd.MM');
  const saved = {};
  readTableC_('_p_lessons').forEach(function (r) { if (r.group === g) saved[r.date] = r; });
  const quizzes = quizRowsC_().filter(function (q) { return q.group === g && q.lesson_date; });
  const quizOf = function (date) {
    const qs = quizzes.filter(function (q) { return q.lesson_date === date; });
    const q = qs.filter(function (x) { return x.status !== 'closed'; })[0] || qs[0];
    return q ? { quiz_id: q.quiz_id, title: q.title, status: q.status } : null;
  };
  const days = data.cols.filter(function (c) { return c.kind === 'day'; });
  const list = days.map(function (c) {
    let marked = 0, nb = 0, sum = 0, cnt = 0;
    data.students.forEach(function (st) {
      const raw = String(st.v[c.c - 1] || '').trim();
      if (!raw) return; marked++;
      if (isAbsent_(raw)) { nb++; return; }   // lesson average: only the students who were there
      const n = Number(raw.replace(',', '.')); if (isFinite(n)) { sum += n; cnt++; }
    });
    return { date: c.h, block: c.block, col: c.c, marked: marked, nb: nb, avg: cnt ? Math.round(sum / cnt * 10) / 10 : null };
  });
  // lessons saved for a date that has no proper gradebook column (e.g. a header typed "5.11")
  Object.keys(saved).forEach(function (d) {
    if (/^\d{2}\.\d{2}$/.test(d) && !days.some(function (c) { return c.h === d; })) list.push({ date: d, block: '', col: null, nocol: true, marked: 0, nb: 0, avg: null });
  });
  list.sort(function (a, b) { return ddmm_(a.date) - ddmm_(b.date); });
  return list.map(function (x, i) {
    const s = saved[x.date] || {};
    x.n = i + 1;
    x.unit = s.unit || ''; x.topic = s.topic || ''; x.focus = s.focus || ''; x.done = s.done || '';
    x.homework = s.homework || ''; x.quiz_id = s.quiz_id || ''; x.notes = s.notes || '';
    x.quiz = quizOf(x.date);
    x.state = x.date === today ? 'today' : ddmm_(x.date) < ddmm_(today) ? 'past' : 'next';
    x.students = data.students.length;
    return x;
  });
}

function apiSaveLesson(t, g, lesson) {
  requireTeacher_(t);
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const obj = {
      group: String(g), date: String(lesson.date),
      unit: lesson.unit || '', topic: lesson.topic || '', done: lesson.done || '',
      homework: lesson.homework || '', notes: lesson.notes || ''
    };
    if (lesson.focus != null) obj.focus = lesson.focus;
    upsertRow_('_p_lessons', function (r) { return r.group === obj.group && r.date === obj.date; }, obj);
    log_('teacher', 'lesson', g + ' | ' + obj.date + ' | ' + obj.topic);
  } finally { lock.releaseLock(); }
  return apiLessons(t, g);
}

/* ---------- Student profile (all numbers computed here) ---------- */

function apiProfile(t, g, row) {
  requireTeacher_(t);
  const data = readGroup_(g, false);
  const st = data.students.filter(function (s) { return s.row === Number(row); })[0];
  if (!st) throw new Error('Student not found.');
  const series = [];
  let sum = 0, cnt = 0, nb = 0;
  data.cols.forEach(function (c) {
    if (c.kind !== 'day') return;
    const raw = String(st.v[c.c - 1] || '').trim();
    let val = null;
    if (isAbsent_(raw)) nb++;
    if (raw.toLowerCase() === 'nb') { /* old absent mark */ }
    else if (raw !== '') { val = Number(raw.replace(',', '.')); if (isFinite(val)) { sum += val; cnt++; } else val = null; }
    series.push({ date: c.h, block: c.block, raw: raw, val: val });
  });
  const summary = {};
  ['Joriy (20)', '1-reyting (20)', '2-reyting (20)', 'MI (10)', 'ON (30)', 'Yakuniygacha (50)', 'YN (50)', 'Jami (100)', 'NB soni', 'Oraliq N (20)']
    .forEach(function (h) {
      const cs = data.cols.filter(function (c) { return c.h === h; });
      summary[h] = cs.map(function (c) { return st.v[c.c - 1]; });
    });
  // group average of attended daily marks, for comparison
  let gs = 0, gc = 0;
  data.students.forEach(function (s) {
    data.cols.forEach(function (c) {
      if (c.kind !== 'day') return;
      const n = Number(String(s.v[c.c - 1] || '').replace(',', '.'));
      if (String(s.v[c.c - 1] || '').trim() !== '' && isFinite(n)) { gs += n; gc++; }
    });
  });
  return {
    name: st.name, row: st.row, series: series,
    avg: cnt ? Math.round(sum / cnt * 10) / 10 : null,
    attended: series.filter(function (x) { return x.raw !== '' && !isAbsent_(x.raw); }).length, nb: nb,
    marked: series.filter(function (x) { return x.raw !== ''; }).length,
    groupAvg: gc ? Math.round(gs / gc * 10) / 10 : null,
    summary: summary,
    quizzes: quizHistory_(g, st.name),
    weak: weakPoints_(g, st.name),
    account: readTable_('_p_students').filter(function (r) { return r.group === String(g) && r.full_name === st.name && (r.status === 'active' || r.status === 'pending'); })
      .map(function (r) { return { status: r.status, tg_username: r.tg_username, linked_at: r.linked_at }; })[0] || null
  };
}

