function apiDeadlines(t, g) {
  requireTeacher_(t);
  const rows = readTable_('_p_deadlines').filter(function (r) { return !g || r.group === String(g) || r.group === 'all'; });
  rows.sort(function (a, b) { return dateKey_(a.due_date) - dateKey_(b.due_date); });
  let pw = null;
  if (g) {
    const data = readGroup_(g, false);
    const pcols = data.cols.filter(function (c) { return /^PW[12]/.test(c.h) || /^MT\d+/.test(c.h) || c.h === 'MI (10)'; });
    pw = {
      cols: pcols,
      students: data.students.map(function (s) {
        return { row: s.row, name: s.name, v: pcols.map(function (c) { return s.v[c.c - 1]; }) };
