  return { deadlines: rows, pw: pw };
}

function apiSaveDeadline(t, d) {
  requireTeacher_(t);
  if (!d.title || !d.due_date) throw new Error('Title and date are required.');
  if (!/^\d{2}\.\d{2}\.\d{4}$/.test(d.due_date)) throw new Error('Date format: dd.mm.yyyy');
  const obj = { id: d.id || newToken_().slice(0, 8), group: d.group || 'all', title: d.title, due_date: d.due_date, type: d.type || 'other', notes: d.notes || '' };
  upsertRow_('_p_deadlines', function (r) { return r.id === obj.id; }, obj);
  log_('teacher', 'deadline', obj.group + ' | ' + obj.title + ' | ' + obj.due_date);
  return apiDeadlines(t, d.viewGroup || '');
}

function apiDeleteDeadline(t, id, viewGroup) {
  requireTeacher_(t);
  const hit = readTable_('_p_deadlines').filter(function (r) { return r.id === id; })[0];
