  return apiDeadlines(t, viewGroup || '');
}

function dateKey_(s) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(String(s));
  return m ? Number(m[3] + m[2] + m[1]) : 99999999;
}

