function apiSetBotToken(t, tok) {
  requireTeacher_(t);
  tok = String(tok || '').trim();
  if (!/^\d+:[A-Za-z0-9_-]{30,}$/.test(tok)) throw new Error('This does not look like a bot token from BotFather.');
  const P = props_(), oldTok = P.getProperty('STUDENT_BOT_TOKEN');
  P.setProperty('STUDENT_BOT_TOKEN', tok);
  let me;
  try { me = tg_('getMe'); } catch (e) {
    if (oldTok) P.setProperty('STUDENT_BOT_TOKEN', oldTok); else P.deleteProperty('STUDENT_BOT_TOKEN');
    throw new Error('Telegram did not accept this token: ' + e.message);
  }
  if (oldTok !== tok) P.deleteProperty('BOT_OFFSET');
  P.setProperty('BOT_USERNAME', me.username);
  tgSafe_('deleteWebhook', { drop_pending_updates: false });
  tgSafe_('setMyCommands', { commands: [{ command: 'start', description: 'Link your account' },
    { command: 'link', description: 'My personal page' }, { command: 'grades', description: 'My marks in short' }] });
  ensureTrigger_();
  log_('teacher', 'setting', 'student bot token updated (@' + me.username + ')');
  return apiSettings(t);
}

