/** Questions this student most often got wrong in quizzes (for the profile). */
function weakPoints_(g, name) {
  const quizzes = {};
  quizRows_().forEach(function (q) { if (q.group === String(g)) quizzes[q.quiz_id] = q; });
  const out = [];
  readTable_('_p_attempts').filter(function (a) { return a.group === String(g) && a.full_name === name; }).forEach(function (a) {
    const q = quizzes[a.quiz_id]; if (!q) return;
    const r = (JSON.parse(a.answers_json || '{}').r) || {};
    JSON.parse(q.questions_json || '[]').forEach(function (x) {
      if (r[x.id] != null && r[x.id] < 1) out.push({ quiz: q.title, prompt: x.prompt, right: correctText_(x), explain: x.explain });
    });
  });
  return out.slice(-8);
}

/** Tokens and settings. Secrets live only in Script Properties. */

function props_() { return PropertiesService.getScriptProperties(); }

function newToken_() {
  return (Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, '').slice(0, 40);
}

function getTeacherToken_() {
  let t = props_().getProperty('TEACHER_TOKEN');
  if (!t) { t = newToken_(); props_().setProperty('TEACHER_TOKEN', t); }
  return t;
}

function isTeacher_(t) {
  const real = props_().getProperty('TEACHER_TOKEN');
  return !!(real && t && String(t) === real);
}

function requireTeacher_(t) {
  if (!isTeacher_(t)) throw new Error('Access denied. Open the panel from your private link.');
}

