/* ---------- _p_settings (non-secret settings) ---------- */

function getSetting_(key, dflt) {
  const sh = pSheet_('_p_settings');
  const vals = sh.getDataRange().getValues();
  for (let i = 1; i < vals.length; i++) if (vals[i][0] === key) return vals[i][1];
  return dflt;
}

function setSetting_(key, value) {
  const sh = pSheet_('_p_settings');
  const vals = sh.getDataRange().getValues();
  for (let i = 1; i < vals.length; i++) {
    if (vals[i][0] === key) { sh.getRange(i + 1, 2).setValue(value); return; }
  }
  sh.appendRow([key, value]);
}

function log_(actor, action, details) {
  try {
    pSheet_('_p_log').appendRow([
      Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyyy-MM-dd HH:mm:ss'), actor, action, details]);
  } catch (e) { /* logging must never break the app */ }
}

/**
 * Student Telegram bot (separate from @ai_yordamchiikki_bot and AI Xizmatkor).
 * No webhook: the 1-minute trigger `tick` polls getUpdates; offset lives in Script Properties.
 * The bot token and the teacher's Telegram id live only in Script Properties.
 */
const SITE_URL = 'https://valisher111.github.io/darslar/';

function studentUrl_(token) {
  const id = webappId_();
  return SITE_URL + 's.html#k=' + token + (id && id !== MAIN_DEPLOYMENT ? '&a=' + id : '');
}

function tg_(method, payload) {
  const tok = props_().getProperty('STUDENT_BOT_TOKEN');
  if (!tok) throw new Error('The student bot is not connected (Settings).');
  const res = UrlFetchApp.fetch('https://api.telegram.org/bot' + tok + '/' + method, {
    method: 'post', contentType: 'application/json', payload: JSON.stringify(payload || {}), muteHttpExceptions: true });
  let j = {};
  try { j = JSON.parse(res.getContentText() || '{}'); } catch (e) { /* not json */ }
  if (!j.ok) throw new Error('Telegram: ' + (j.description || ('HTTP ' + res.getResponseCode())));
  return j.result;
}
function tgSafe_(method, payload) {
  try { return tg_(method, payload); } catch (e) { log_('bot', 'tg-error', method + ': ' + e.message); return null; }
}
function h_(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function send_(chat, text, buttons) {
  const p = { chat_id: chat, text: text, parse_mode: 'HTML', disable_web_page_preview: true };
  if (buttons) p.reply_markup = { inline_keyboard: buttons };
  return tgSafe_('sendMessage', p);
}
function edit_(chat, mid, text, buttons) {
  const p = { chat_id: chat, message_id: mid, text: text, parse_mode: 'HTML', disable_web_page_preview: true };
  p.reply_markup = { inline_keyboard: buttons || [] };
  return tgSafe_('editMessageText', p) || send_(chat, text, buttons);
}

/** One 1-minute trigger for everything that must run on its own. */
function ensureTrigger_() {
  const has = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'tick'; });
  if (!has) ScriptApp.newTrigger('tick').timeBased().everyMinutes(1).create();
}

function tick() {
  try { closeExpiredQuizzes_(); } catch (e) { log_('system', 'tick-quiz-error', e.message); }
  try { autoCloseStale_(); } catch (e) { log_('system', 'tick-stale-error', e.message); }
  try { remindDeadlines_(); } catch (e) { log_('bot', 'remind-error', e.message); }
  try { pollBot_(); } catch (e) { log_('bot', 'poll-error', e.message); }
  try { sendOutbox_(); } catch (e) { log_('bot', 'outbox-error', e.message); }
  try { closeExpiredPersonal_(); } catch (e) { log_('personal', 'tick-error', e.message); }
}

/* Personal messages queued by the teacher: _p_outbox rows with status "ready" go out on the next tick
   (HTML text, student found by group + full_name in _p_students). Status → sending → sent / error: … */
function sendOutbox_() {
  const sh = pSheet_('_p_outbox');
  const vals = sh.getDataRange().getValues();
  if (vals.length < 2) return;
  const H = vals[0].map(String), col = function (n) { return H.indexOf(n); };
  const rows = [];
  for (let i = 1; i < vals.length; i++) if (String(vals[i][col('status')]).trim() === 'ready') rows.push(i);
  if (!rows.length) return;
  rows.forEach(function (i) { sh.getRange(i + 1, col('status') + 1).setValue('sending'); });
  SpreadsheetApp.flush();
  const acc = accounts_();
  rows.slice(0, 25).forEach(function (i) {
    const r = vals[i], g = String(r[col('group')]).trim(), n = String(r[col('full_name')]).trim();
    const a = acc.filter(function (x) { return x.group === g && x.full_name === n && x.status === 'active' && x.tg_id; })[0];
    const st = !a ? 'error: not linked' : (send_(a.tg_id, String(r[col('text')]), col('button') >= 0 && String(r[col('button')] || '').trim() ? [[{ text: String(r[col('button')]).trim(), url: studentUrl_(a.token) }]] : null) ? 'sent' : 'error: telegram');
    sh.getRange(i + 1, col('status') + 1, 1, 3).setValues([[st, r[col('created_at')], Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyyy-MM-dd HH:mm:ss')]]);
    log_('teacher', 'outbox', g + ' / ' + n + ' → ' + st);
  });
  rows.slice(25).forEach(function (i) { sh.getRange(i + 1, col('status') + 1).setValue('ready'); });
}

function pollBot_() {
  const P = props_();
  if (!P.getProperty('STUDENT_BOT_TOKEN')) return;
  const hour = Number(Utilities.formatDate(new Date(), 'Asia/Tashkent', 'H'));
  if (hour < 6) return; // quiet hours 00:00–06:00: messages wait until morning
  const offset = Number(P.getProperty('BOT_OFFSET') || 0);
  const ups = tg_('getUpdates', { offset: offset, timeout: 0, limit: 50, allowed_updates: ['message', 'callback_query', 'my_chat_member'] });
  if (!ups || !ups.length) return;
  P.setProperty('BOT_OFFSET', String(ups[ups.length - 1].update_id + 1));
  ups.forEach(function (u) {
    try { handleUpdate_(u); } catch (e) { log_('bot', 'update-error', e.message); }
  });
}

/* ---------- accounts (_p_students) ---------- */

function accounts_() { return readTable_('_p_students'); }

function accountByTg_(id) {
  const rows = accounts_().filter(function (r) { return r.tg_id === String(id) && (r.status === 'active' || r.status === 'pending'); });
  return rows.filter(function (r) { return r.status === 'active'; })[0] || rows[0] || null;
}

function takenNames_(g, exceptTg) {
  const out = {};
  accounts_().forEach(function (r) {
    if (r.group === String(g) && (r.status === 'active' || r.status === 'pending') && r.tg_id !== String(exceptTg)) out[r.full_name] = r.status;
  });
  return out;
}

function botGroups_() { return listGroups_().filter(function (g) { return g !== 'TEST'; }); }

/* ---------- updates ---------- */

function isTeacherTg_(id) { return String(id) === String(props_().getProperty('TEACHER_TG_ID') || '-'); }

function handleUpdate_(u) {
  if (u.callback_query) return handleCallback_(u.callback_query);
  if (u.my_chat_member) {   // the bot was added to / removed from a group chat: remember it for the Groups page
    const st = (u.my_chat_member.new_chat_member || {}).status;
    return noteChat_(u.my_chat_member.chat, st === 'left' || st === 'kicked');
  }
  if (u.message && u.message.chat && u.message.chat.type !== 'private') {
    if (u.message.migrate_to_chat_id) return migrateChat_(u.message.chat.id, u.message.migrate_to_chat_id, u.message.chat.title);
    return noteChat_(u.message.chat, !!(u.message.left_chat_member && u.message.left_chat_member.is_bot));
  }
  const m = u.message;
  if (!m || !m.chat || m.chat.type !== 'private' || !m.text) return;
  const from = m.from, chat = m.chat.id, parts = m.text.trim().split(/\s+/);
  const cmd = parts[0].toLowerCase().replace(/@.*$/, ''), arg = parts[1] || '';
  if (cmd === '/start' && /^admin_/.test(arg)) return adminConnect_(from, chat, arg.slice(6));
  if (isTeacherTg_(from.id)) return teacherCmd_(chat, cmd);
  const me = accountByTg_(from.id);
  const active = me && me.status === 'active';
  if (cmd === '/link' && active) return sendLink_(chat, me);
  if (cmd === '/grades' && active) return sendGrades_(chat, me);
  if (cmd === '/start' || cmd === '/link' || cmd === '/grades') return studentStart_(chat, me);
  send_(chat, 'Commands:\n/start — link your account\n/link — your personal page\n/grades — your marks in short\n\nQuestions about lessons? Write in your group chat.');
}

function studentStart_(chat, me) {
  if (me && me.status === 'active') {
    return send_(chat, 'You are linked as <b>' + h_(me.full_name) + '</b> (group ' + h_(me.group) + ').',
      [[{ text: 'Open my page', url: studentUrl_(me.token) }]]);
  }
  if (me && me.status === 'pending') {
    return send_(chat, 'Your request (<b>' + h_(me.full_name) + '</b>, group ' + h_(me.group) + ') is waiting for your teacher\'s approval. You will get your link here.',
      [[{ text: 'I chose the wrong name', callback_data: 'x' }]]);
  }
  send_(chat, 'Welcome to <b>Darslar</b>! Here you will see your marks, homework and quiz results.\n\nChoose your group:', groupButtons_());
}

function groupButtons_() {
  const gs = botGroups_(), rows = [];
  for (let i = 0; i < gs.length; i += 3) rows.push(gs.slice(i, i + 3).map(function (g) { return { text: g, callback_data: 'g:' + g }; }));
  return rows;
}

function handleCallback_(q) {
  const data = String(q.data || ''), from = q.from;
  const chat = q.message && q.message.chat.id, mid = q.message && q.message.message_id;
  tgSafe_('answerCallbackQuery', { callback_query_id: q.id });
  const p = data.split(':');
  if (p[0] === 'a' || p[0] === 'r') {
    if (!isTeacherTg_(from.id)) return;
    let msg;
    try { msg = p[0] === 'a' ? approve_(p[1], 'bot') : reject_(p[1], 'bot'); } catch (e) { msg = e.message; }
    return edit_(chat, mid, msg);
  }
  if (isTeacherTg_(from.id)) return;
  const me = accountByTg_(from.id);
  if (me && me.status === 'active') return edit_(chat, mid, 'You are already linked as <b>' + h_(me.full_name) + '</b>. Send /link to get your page.');
  if (p[0] === 'x') {
    if (me && me.status === 'pending') setAccount_(me.group, me.full_name, { status: 'cancelled' });
    return edit_(chat, mid, 'Request cancelled. Choose your group:', groupButtons_());
  }
  if (p[0] === 'back') return edit_(chat, mid, 'Choose your group:', groupButtons_());
  if (p[0] === 'g') {
    const g = p[1];
    if (botGroups_().indexOf(g) < 0) return;
    const taken = takenNames_(g, from.id);
    const free = readGroup_(g, false).students.filter(function (s) { return !taken[s.name]; });
    const rows = [];
    for (let i = 0; i < free.length; i += 2) rows.push(free.slice(i, i + 2).map(function (s) { return { text: s.name, callback_data: 'n:' + g + ':' + s.row }; }));
    rows.push([{ text: '« Back', callback_data: 'back' }]);
    return edit_(chat, mid, 'Group <b>' + h_(g) + '</b>. Tap your name' + (free.length ? ':' : ' — all names are taken. Ask your teacher.'), rows);
  }
  if (p[0] === 'n') {
    const g = p[1], row = Number(p[2]);
    const st = readGroup_(g, false).students.filter(function (s) { return s.row === row; })[0];
    if (!st) return edit_(chat, mid, 'Name not found. Send /start again.');
    if (takenNames_(g, from.id)[st.name]) return edit_(chat, mid, 'This name is already linked to another Telegram account. If it is yours, tell your teacher.');
    const lock = LockService.getScriptLock(); lock.waitLock(20000);
    try {
      accounts_().forEach(function (r) {
        if (r.tg_id === String(from.id) && r.status === 'pending') setAccount_(r.group, r.full_name, { status: 'cancelled' });
      });
      setAccount_(g, st.name, { tg_id: String(from.id), tg_username: from.username || '', token: '', status: 'pending',
        linked_at: Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyyy-MM-dd HH:mm') });
    } finally { lock.releaseLock(); }
    log_('bot', 'request', g + ' | ' + st.name + ' | tg ' + from.id);
    edit_(chat, mid, 'Thank you! Request sent: <b>' + h_(st.name) + '</b>, group ' + h_(g) + '.\nYou will get your personal link here after your teacher approves it.',
      [[{ text: 'I chose the wrong name', callback_data: 'x' }]]);
    const tId = props_().getProperty('TEACHER_TG_ID');
    if (tId) send_(tId, 'New student request\n<b>' + h_(st.name) + '</b> — group ' + h_(g) +
      '\nTelegram: ' + h_(from.first_name || '') + ' ' + h_(from.last_name || '') + (from.username ? ' @' + h_(from.username) : ''),
      [[{ text: '✅ Approve', callback_data: 'a:' + from.id }, { text: '✖ Reject', callback_data: 'r:' + from.id }]]);
  }
}

function setAccount_(g, name, patch) {
  const obj = { group: String(g), full_name: name };
  Object.keys(patch).forEach(function (k) { obj[k] = patch[k]; });
  upsertRow_('_p_students', function (r) { return r.group === String(g) && r.full_name === name; }, obj);
}

function approve_(tgid, actor) {
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  let acc;
  try {
    const all = accounts_();
    acc = all.filter(function (r) { return r.tg_id === String(tgid) && r.status === 'pending'; })[0];
    if (!acc) throw new Error('This request is no longer waiting (already approved, rejected or cancelled).');
    // duplicate request rows for the same name (double tap): keep the active one, close the others
    const twin = all.filter(function (r) { return r._row !== acc._row && r.group === acc.group && r.full_name === acc.full_name && r.status === 'active'; })[0];
    all.forEach(function (r) {
      if (r._row !== acc._row && r.tg_id === String(tgid) && r.group === acc.group && r.full_name === acc.full_name && r.status === 'pending')
        patchRowAt_('_p_students', r, { status: 'duplicate' });
    });
    if (twin && twin.tg_id === String(tgid)) {
      patchRowAt_('_p_students', acc, { status: 'duplicate' });
      log_(actor === 'bot' ? 'teacher-bot' : 'teacher', 'approve-dup', acc.group + ' | ' + acc.full_name);
      return '✅ Already approved: <b>' + h_(acc.full_name) + '</b> (' + h_(acc.group) + ')';
    }
    if (twin) throw new Error(acc.full_name + ' is already linked to another Telegram account. Unlink it first.');
    acc.token = newToken_();
    patchRowAt_('_p_students', acc, { token: acc.token, status: 'active',
      linked_at: Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyyy-MM-dd HH:mm') });
  } finally { lock.releaseLock(); }
  log_(actor === 'bot' ? 'teacher-bot' : 'teacher', 'approve', acc.group + ' | ' + acc.full_name);
  sendLink_(acc.tg_id, acc, true);
  return '✅ Approved: <b>' + h_(acc.full_name) + '</b> (' + h_(acc.group) + ')';
}

function reject_(tgid, actor) {
  const acc = accounts_().filter(function (r) { return r.tg_id === String(tgid) && r.status === 'pending'; })[0];
  if (!acc) throw new Error('This request is no longer waiting.');
  patchRowAt_('_p_students', acc, { status: 'rejected' });
  log_(actor === 'bot' ? 'teacher-bot' : 'teacher', 'reject', acc.group + ' | ' + acc.full_name);
  send_(acc.tg_id, 'Your request for <b>' + h_(acc.full_name) + '</b> was not approved. Send /start to choose again.');
  return '✖ Rejected: <b>' + h_(acc.full_name) + '</b> (' + h_(acc.group) + ')';
}

function sendLink_(chat, acc, first) {
  send_(chat, (first ? 'Your account is ready, <b>' + h_(acc.full_name) + '</b>!\n\n' : '') +
    'This is your personal page. Do not share the link: it opens your marks without a password.',
    [[{ text: 'Open my page', url: studentUrl_(acc.token) }]]);
}

function sendGrades_(chat, acc) {
  const s = studentSummary_(acc.group, acc.full_name);
  const lines = ['<b>' + h_(acc.full_name) + '</b> · group ' + h_(acc.group),
    'Average daily mark: <b>' + (s.avg == null ? '—' : s.avg) + '</b> (group ' + (s.groupAvg == null ? '—' : s.groupAvg) + ')',
    'Lessons attended: ' + s.attended + '/' + s.marked + (s.nb ? ' · absences: ' + s.nb : ''),
    s.rank ? 'Your place: ' + s.rank + ' of ' + s.ranked : ''];
  if (s.last.length) lines.push('Last marks: ' + s.last.map(function (x) { return x.date + ' — ' + x.raw; }).join(', '));
  send_(chat, lines.filter(String).join('\n'), [[{ text: 'Open my page', url: studentUrl_(acc.token) }]]);
}

/* ---------- teacher in the bot ---------- */

function adminConnect_(from, chat, code) {
  const cache = CacheService.getScriptCache();
  const real = cache.get('admin_code');
  if (!real || real !== code) return send_(chat, 'This connect link has expired. Open Settings in Darslar and press "Connect my Telegram" again.');
  cache.remove('admin_code');
  props_().setProperty('TEACHER_TG_ID', String(from.id));
  log_('teacher', 'tg-connected', String(from.id));
  send_(chat, 'Done. You are connected as the <b>teacher</b>. New student requests will come here with Approve / Reject buttons.\n/pending — requests waiting now');
}

function teacherCmd_(chat, cmd) {
  if (cmd === '/pending' || cmd === '/start') {
    const pend = accounts_().filter(function (r) { return r.status === 'pending'; });
    if (!pend.length) return send_(chat, 'No requests waiting. ✔');
    pend.forEach(function (r) {
      send_(chat, 'Request: <b>' + h_(r.full_name) + '</b> — group ' + h_(r.group) + (r.tg_username ? ' (@' + h_(r.tg_username) + ')' : ''),
        [[{ text: '✅ Approve', callback_data: 'a:' + r.tg_id }, { text: '✖ Reject', callback_data: 'r:' + r.tg_id }]]);
    });
    return;
  }
  send_(chat, 'You are the teacher here. Student requests come to this chat.\n/pending — requests waiting now');
}

/* ---------- teacher API (site) ---------- */

function apiAccounts(t, g) {
  requireTeacher_(t);
  const all = accounts_();
  const by = {};
  all.forEach(function (r) {
    if (r.group !== String(g)) return;
    if (r.status === 'active' || r.status === 'pending') by[r.full_name] = { status: r.status, tg_username: r.tg_username, linked_at: r.linked_at, tg_id: r.tg_id };
  });
  return {
    botSet: !!props_().getProperty('STUDENT_BOT_TOKEN'),
    botUsername: props_().getProperty('BOT_USERNAME') || '',
    teacherLinked: !!props_().getProperty('TEACHER_TG_ID'),
    pending: all.filter(function (r) { return r.status === 'pending'; })
      .map(function (r) { return { group: r.group, full_name: r.full_name, tg_id: r.tg_id, tg_username: r.tg_username, at: r.linked_at }; }),
    byName: by
  };
}

function apiApprove(t, tgid, g) { requireTeacher_(t); approve_(tgid, 'site'); return apiAccounts(t, g); }
function apiReject(t, tgid, g) { requireTeacher_(t); reject_(tgid, 'site'); return apiAccounts(t, g); }
function apiApproveAll(t, g) {
  requireTeacher_(t);
  const ids = accounts_().filter(function (r) { return r.status === 'pending'; }).map(function (r) { return r.tg_id; });
  let ok = 0; const failed = [];
  ids.forEach(function (id) { try { approve_(id, 'site'); ok++; } catch (e) { failed.push(String(e.message || e)); } });
  const res = apiAccounts(t, g); res.approved = ok; res.failed = failed.length; return res;
}

function apiUnlink(t, g, name) {
  requireTeacher_(t);
  const acc = accounts_().filter(function (r) { return r.group === String(g) && r.full_name === name && (r.status === 'active' || r.status === 'pending'); })[0];
  if (!acc) throw new Error('This student has no linked Telegram account.');
  if (acc.token) CacheService.getScriptCache().remove('stu_' + acc.token);
  setAccount_(g, name, { status: 'unlinked', token: '' });
  log_('teacher', 'unlink', g + ' | ' + name);
  if (acc.tg_id) send_(acc.tg_id, 'Your Darslar account was unlinked by your teacher. Send /start to link again.');
  return apiAccounts(t, g);
}

/** Deep link that connects Valisher's own Telegram as the teacher (valid 15 min). */
function apiTeacherTgLink(t) {
  requireTeacher_(t);
  const u = props_().getProperty('BOT_USERNAME');
  if (!u) throw new Error('Connect the student bot first (paste its token).');
  const code = newToken_().slice(0, 12);
  CacheService.getScriptCache().put('admin_code', code, 900);
  return 'https://t.me/' + u + '?start=admin_' + code;
}

