function route_(action, key, args) {
  if (OPEN_ACTIONS[action]) return OPEN_ACTIONS[action](args);
  if (ST_ACTIONS[action]) {
    const me = studentByToken_(key);
    if (!me) throw new Error('LINK_INVALID');
    return ST_ACTIONS[action].apply(null, [me].concat(args));
  }
  if (!KEY_ACTIONS[action]) throw new Error('Unknown action: ' + action);
  if (!isTeacher_(key)) throw new Error('SESSION_EXPIRED');
  return KEY_ACTIONS[action].apply(null, [key].concat(args));
}

/* ---------- password ---------- */

function hash_(pw, salt) {
  const bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, salt + '|' + pw, Utilities.Charset.UTF_8);
  return Utilities.base64Encode(bytes);
}

function login_(pw) {
  const cache = CacheService.getScriptCache();
  const fails = Number(cache.get('pw_fails') || 0);
  if (fails >= 8) throw new Error('Too many wrong attempts. Try again in 10 minutes.');
  const h = props_().getProperty('PW_HASH'), salt = props_().getProperty('PW_SALT');
  if (!h) throw new Error('Password is not set yet. Open the setup link first.');
  Utilities.sleep(400);
  if (hash_(String(pw || ''), salt) !== h) {
    cache.put('pw_fails', String(fails + 1), 600);
    throw new Error('Wrong password.');
  }
  cache.remove('pw_fails');
  log_('teacher', 'login', 'site');
  return { key: getTeacherToken_() };
}

function setPassword_(setupKey, pw) {
  if (props_().getProperty('PW_HASH') && !isTeacher_(setupKey)) throw new Error('Password already set.');
  if (!isTeacher_(setupKey)) throw new Error('This setup link is not valid.');
  storePassword_(pw);
  // the setup link stops working: issue a fresh key
  props_().setProperty('TEACHER_TOKEN', newToken_());
  log_('teacher', 'password', 'set');
  return { key: getTeacherToken_() };
}

function storePassword_(pw) {
  pw = String(pw || '');
  if (pw.length < 6) throw new Error('Password must be at least 6 characters.');
  const salt = newToken_().slice(0, 16);
  props_().setProperties({ PW_SALT: salt, PW_HASH: hash_(pw, salt) });
}

function apiChangePassword(t, oldPw, newPw) {
  requireTeacher_(t);
  if (hash_(String(oldPw || ''), props_().getProperty('PW_SALT')) !== props_().getProperty('PW_HASH')) throw new Error('Current password is wrong.');
  storePassword_(newPw);
  log_('teacher', 'password', 'changed');
  return true;
}

/** Signs out every device: new key; the site asks for the password again. */
function apiLogoutAll(t) {
  requireTeacher_(t);
  props_().setProperty('TEACHER_TOKEN', newToken_());
  log_('teacher', 'logout-all', '');
  return true;
}

/* ---------- home (today) ---------- */

function apiHome(t) {
  requireTeacher_(t);
  try { seedLessons_(); } catch (e) { log_('system', 'lessons-seed-error', String(e)); }
  const now = new Date();
  const today = Utilities.formatDate(now, 'Asia/Tashkent', 'dd.MM');
  const year = Number(Utilities.formatDate(now, 'Asia/Tashkent', 'yyyy'));
  const lessonsAll = readTableC_('_p_lessons');
  const quizAll = quizRowsC_().filter(function (r) { return r.lesson_date && r.status !== 'closed'; });
  const groups = listGroups_().filter(function (g) { return g !== 'TEST'; });
  const todayList = [], upcoming = [], cards = [];
  groups.forEach(function (g) {
    const d = readGroup_(g, false);
    const days = d.cols.filter(function (c) { return c.kind === 'day'; });
    const info = function (date) {
      const l = lessonsAll.filter(function (r) { return r.group === g && r.date === date; })[0] || {};
      const c = days.filter(function (x) { return x.h === date; })[0];
      let marked = 0;
      if (c) d.students.forEach(function (s) { if (String(s.v[c.c - 1] || '').trim() !== '') marked++; });
      const qz = quizAll.filter(function (r) { return r.group === g && r.lesson_date === date; })[0];
      return { group: g, subject: subjectOf_(g), date: date, col: c ? c.c : null, n: days.indexOf(c) + 1,
        unit: l.unit || '', topic: l.topic || '', focus: l.focus || '', homework: l.homework || '', marked: marked, students: d.students.length,
        quiz: qz ? { quiz_id: qz.quiz_id, title: qz.title, status: qz.status } : null };
    };
    if (days.some(function (c) { return c.h === today; })) todayList.push(info(today));
    days.filter(function (c) { return ddmm_(c.h) > ddmm_(today); }).slice(0, 2)
      .forEach(function (c) { upcoming.push(info(c.h)); });
    // group card: averages over attended daily marks
    let sum = 0, cnt = 0, nb = 0, last = '';
    days.forEach(function (c) {
      let any = false;
      d.students.forEach(function (s) {
        const raw = String(s.v[c.c - 1] || '').trim();
        if (!raw) return; any = true;
        if (isAbsent_(raw)) nb++;
        if (raw.toLowerCase() === 'nb') return;
        const n = Number(raw.replace(',', '.')); if (isFinite(n)) { sum += n; cnt++; }
      });
      if (any) last = c.h;
    });
    cards.push({ group: g, subject: subjectOf_(g), students: d.students.length,
      avg: cnt ? Math.round(sum / cnt * 10) / 10 : null, nb: nb, lastLesson: last,
      lessonsDone: days.filter(function (c) { return ddmm_(c.h) <= ddmm_(last); }).length, lessonsTotal: days.length });
  });
  upcoming.sort(function (a, b) { return ddmm_(a.date) - ddmm_(b.date); });
  const dls = readTableC_('_p_deadlines').map(function (r) {
    const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(r.due_date);
    const due = m ? new Date(+m[3], +m[2] - 1, +m[1]) : null;
    const base = new Date(year, Number(today.slice(3)) - 1, Number(today.slice(0, 2)));
    r.days = due ? Math.round((due - base) / 864e5) : null;
    return r;
  }).filter(function (r) { return r.days != null && r.days >= -3 && r.days <= 30; })
    .sort(function (a, b) { return a.days - b.days; });
  return { today: today, todayLessons: todayList, upcoming: upcoming.slice(0, 6), groups: cards, deadlines: dls };
}

/** Sortable key for dd.MM inside one academic year (Sep→Aug). */
function ddmm_(s) {
  const m = /^(\d{2})\.(\d{2})$/.exec(String(s || ''));
  if (!m) return 0;
  let mo = Number(m[2]); if (mo < 8) mo += 12;
  return mo * 100 + Number(m[1]);
}

/**
 * Added 10.11.2026:
 *  - "Finish lesson": empty cells → 0 (absent) or the student's average, lesson summary, marks picture to the group chat;
 *  - "Fill with averages" (Valisher's rule of 08.11: average of the daily marks before that date, 0 counts, nb and empty do not, 1 decimal);
 *  - deadline reminders to students (student bot), once a day;
 *  - "Practice my mistakes" for students (nothing is written to the gradebook);
 *  - an opened quiz / live game never stays open after the end of the next day.
 */

/* Old fixed list (Valisher, AI Xizmatkor): only seeds _p_groups once. Chats now live in _p_groups (Groups page). */
const GROUP_CHATS = {};

/* ---------- fill with averages ---------- */

/** Students whose cell on `date` is empty, with the average of their daily marks before that date. Nothing is written. */
function avgFillRows_(g, date) {
  const d = readGroup_(g, true);
  const days = d.cols.filter(function (c) { return c.kind === 'day'; });
  const col = days.filter(function (c) { return c.h === date; })[0];
  if (!col) throw new Error('No date column ' + date + ' in group ' + g + '.');
  const before = days.filter(function (c) { return ddmm_(c.h) < ddmm_(date); });
  return d.students.filter(function (s) { return String(s.v[col.c - 1] || '').trim() === ''; }).map(function (s) {
    let sum = 0, n = 0;
    before.forEach(function (c) {
      const raw = String(s.v[c.c - 1] || '').trim();
      if (!raw || raw.toLowerCase() === 'nb') return;
      const v = Number(raw.replace(',', '.'));
      if (isFinite(v)) { sum += v; n++; }
    });
    return { row: s.row, name: s.name, col: col.c, avg: n ? round1_(sum / n) : null, n: n };
  });
}

function apiAvgFill(t, g, date) {
  requireTeacher_(t);
  return avgFillRows_(String(g), String(date));
}

