/** What the "Finish lesson" window needs: empty students (with averages), quiz of that date, chat, bot. */
function apiFinishCheck(t, g, date) {
  requireTeacher_(t);
  g = String(g); date = String(date);
  const rows = avgFillRows_(g, date);
  const d = readGroup_(g, false);
  const col = d.cols.filter(function (c) { return c.kind === 'day' && c.h === date; })[0];
  const played = {};
  const qz = quizRowsC_().filter(function (q) { return q.group === g && q.lesson_date === date && q.status === 'closed'; });
  if (qz.length) readTableC_('_p_attempts').forEach(function (a) { if (qz.some(function (q) { return q.quiz_id === a.quiz_id; })) played[a.full_name] = 1; });
  const lesson = readTableC_('_p_lessons').filter(function (r) { return r.group === g && r.date === date; })[0] || {};
  return { group: g, date: date, students: d.students.length, empty: rows, quiz: qz.map(function (q) { return q.title; }),
    quizPlayed: Object.keys(played).length, chat: !!chatOf_(g), botSet: !!(props_().getProperty('GROUP_BOT_TOKEN') || props_().getProperty('STUDENT_BOT_TOKEN')),
    lesson: { unit: lesson.unit || '', topic: lesson.topic || '', done: lesson.done || '' }, col: col ? col.c : null };
}

/**
 * entries: [{row, value}] for empty cells (0 = absent, or a mark). Writes them, saves a short summary to the lesson
 * and returns the fresh group (for the marks picture).
 */
function apiFinishLesson(t, g, date, entries, note) {
  requireTeacher_(t);
  g = String(g); date = String(date);
  const d0 = readGroup_(g, true);
  const col = d0.cols.filter(function (c) { return c.kind === 'day' && c.h === date; })[0];
  if (!col) throw new Error('No date column ' + date + ' in group ' + g + '.');
  const empty = {};
  d0.students.forEach(function (s) { if (String(s.v[col.c - 1] || '').trim() === '') empty[s.row] = 1; });
  const list = (entries || []).filter(function (e) { return empty[Number(e.row)]; })
    .map(function (e) { return { row: Number(e.row), col: col.c, value: e.value }; });
  if (list.length) writeCells_(g, list, 'teacher');
  const d = readGroup_(g, true);
  let marked = 0, absent = 0, sum = 0, n = 0;
  d.students.forEach(function (s) {
    const raw = String(s.v[col.c - 1] || '').trim();
    if (!raw) return; marked++;
    if (isAbsent_(raw)) { absent++; return; }
    const v = Number(raw.replace(',', '.')); if (isFinite(v)) { sum += v; n++; }
  });
  const avg = n ? round1_(sum / n) : null;
  const auto = '✓ Marks ' + marked + '/' + d.students.length + (absent ? ' · absent ' + absent : '') + (avg != null ? ' · average ' + avg : '') +
    (note ? ' · ' + String(note).slice(0, 120) : '');
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const old = readTable_('_p_lessons').filter(function (r) { return r.group === g && r.date === date; })[0];
    const prev = old ? String(old.done || '').split(' | ').filter(function (x) { return x && x.indexOf('✓ Marks') !== 0; }) : [];
    upsertRow_('_p_lessons', function (r) { return r.group === g && r.date === date; },
      { group: g, date: date, done: prev.concat([auto]).join(' | ') });
  } finally { lock.releaseLock(); }
  log_('teacher', 'finish-lesson', g + ' | ' + date + ' | ' + list.length + ' cells | ' + auto);
  return { written: list.length, marked: marked, absent: absent, avg: avg, students: d.students.length, group: d };
}

/* ---------- marks picture to the group chat (AI Xizmatkor) ---------- */

function groupTg_(method, payload, multipart) {
  // a separate group bot if the teacher set one (Valisher: AI Xizmatkor), otherwise the student bot itself
  const tok = props_().getProperty('GROUP_BOT_TOKEN') || props_().getProperty('STUDENT_BOT_TOKEN');
  if (!tok) throw new Error('The bot is not connected yet. Settings → Student bot.');
  const o = { method: 'post', muteHttpExceptions: true };
  if (multipart) o.payload = payload; else { o.contentType = 'application/json'; o.payload = JSON.stringify(payload || {}); }
  const res = UrlFetchApp.fetch('https://api.telegram.org/bot' + tok + '/' + method, o);
  let j = {};
  try { j = JSON.parse(res.getContentText() || '{}'); } catch (e) { /* not json */ }
  if (!j.ok) throw new Error('Telegram: ' + (j.description || ('HTTP ' + res.getResponseCode())));
  return j.result;
}

function apiSendGroupPhoto(t, g, b64, caption) {
  requireTeacher_(t);
  const chat = chatOf_(g);
  if (!chat) throw new Error('Group ' + g + ' has no Telegram chat yet. Groups → ' + g + ' → Telegram chat.');
  const data = String(b64 || '').replace(/^data:image\/png;base64,/, '');
  if (!data || data.length > 8e6) throw new Error('The picture is empty or too big.');
  const blob = Utilities.newBlob(Utilities.base64Decode(data), 'image/png', 'baholar-' + g + '.png');
  groupTg_('sendPhoto', { chat_id: chat, caption: String(caption || '').slice(0, 900), photo: blob }, true);
  log_('teacher', 'group-photo', g + ' | ' + String(caption || '').slice(0, 80));
  return true;
}

function apiSetGroupBot(t, tok) {
  requireTeacher_(t);
  tok = String(tok || '').trim();
  const P = props_();
  if (!tok) { P.deleteProperty('GROUP_BOT_TOKEN'); log_('teacher', 'setting', 'group bot removed'); return apiSettings(t); }
  if (!/^\d+:[A-Za-z0-9_-]{30,}$/.test(tok)) throw new Error('This does not look like a bot token from BotFather.');
  if (tok === P.getProperty('STUDENT_BOT_TOKEN')) throw new Error('This is already your student bot: it sends the pictures by itself. Leave this field empty.');
  const old = P.getProperty('GROUP_BOT_TOKEN');
  P.setProperty('GROUP_BOT_TOKEN', tok);
  let me;
  try { me = groupTg_('getMe'); } catch (e) {
    if (old) P.setProperty('GROUP_BOT_TOKEN', old); else P.deleteProperty('GROUP_BOT_TOKEN');
    throw new Error('Telegram did not accept this token: ' + e.message);
  }
  P.setProperty('GROUP_BOT_USERNAME', me.username);
  log_('teacher', 'setting', 'group bot connected (@' + me.username + ')');
  return apiSettings(t);
}

