/** Once a day after 18:00 (Tashkent): deadlines due in 3 days or tomorrow → every linked student of that group. */
function remindDeadlines_(force) {
  const P = props_();
  if (!P.getProperty('STUDENT_BOT_TOKEN')) return 0;
  const now = new Date(), day = Utilities.formatDate(now, 'Asia/Tashkent', 'yyyy-MM-dd');
  if (!force) {
    if (Number(Utilities.formatDate(now, 'Asia/Tashkent', 'H')) < 18) return 0;
    if (P.getProperty('REMIND_DAY') === day) return 0;
    P.setProperty('REMIND_DAY', day);
    if (String(getSetting_('deadlineReminders', 'on')) !== 'on') return 0;
  }
  const base = new Date(day + 'T00:00:00Z');
  const due = readTable_('_p_deadlines').map(function (r) {
    const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(r.due_date);
    r.days = m ? Math.round((new Date(m[3] + '-' + m[2] + '-' + m[1] + 'T00:00:00Z') - base) / 864e5) : null;
    return r;
  }).filter(function (r) { return r.days === 3 || r.days === 1; });
  if (!due.length) return 0;
  const accs = readTable_('_p_students').filter(function (a) { return a.status === 'active' && a.tg_id; });
  let sent = 0;
  due.forEach(function (r) {
    const when = r.days === 1 ? 'tomorrow' : 'in 3 days';
    const dt = (function () { const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(r.due_date); return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'short', timeZone: 'UTC' }); })();
    accs.filter(function (a) { return a.group !== 'TEST' && (r.group === 'all' || a.group === r.group); }).forEach(function (a) {
      if (send_(a.tg_id, '⏰ <b>Reminder</b>\n<b>' + h_(r.title) + '</b> is due ' + when + ' (' + h_(dt) + ').' + (r.notes ? '\n' + h_(r.notes) : ''),
        [[{ text: 'Open my page', url: studentUrl_(a.token) }]])) sent++;
    });
    log_('bot', 'deadline-reminder', r.group + ' | ' + r.title + ' | ' + when);
  });
  return sent;
}

/* ---------- an opened quiz / live game closes by itself at the end of the next day ---------- */

function dayIndex_(d) { return Math.round(new Date(Utilities.formatDate(d, 'Asia/Tashkent', 'yyyy-MM-dd') + 'T00:00:00Z').getTime() / 864e5); }

function autoCloseStale_() {
  const today = dayIndex_(new Date());
  const L = liveGet_();
  if (L && L.opened && today - dayIndex_(new Date(L.opened)) >= 2) {
    props_().deleteProperty('LIVE');
    log_('system', 'live-auto-close', L.group + ' | ' + L.quiz_id + ' | opened ' + L.opened + ' (no marks saved)');
  }
  const m = openMap_();
  Object.keys(m).forEach(function (id) {
    let q; try { q = getQuiz_(id); } catch (e) { return; }
    if (q.opened_at && today - dayIndex_(new Date(q.opened_at)) >= 2) finalizeQuiz_(id);
  });
}

/** Latest moment an opened quiz may stay open: 23:59 of the next day (Tashkent). */
function latestClose_(openedIso) {
  const day = Utilities.formatDate(new Date(openedIso), 'Asia/Tashkent', 'yyyy-MM-dd');
  return new Date(new Date(day + 'T23:59:00+05:00').getTime() + 864e5);
}

/* ---------- student: practice my mistakes (nothing is written) ---------- */

function practicePool_(me) {
  const quizzes = {};
  quizRowsC_().forEach(function (q) { if (q.group === me.group && q.status === 'closed') quizzes[q.quiz_id] = q; });
  const out = [];
  readTableC_('_p_attempts').filter(function (a) { return a.group === me.group && a.full_name === me.name && quizzes[a.quiz_id]; })
    .sort(function (a, b) { return String(b.submitted_at).localeCompare(String(a.submitted_at)); })
    .forEach(function (a) {
      const q = quizzes[a.quiz_id], r = (JSON.parse(a.answers_json || '{}').r) || {};
      JSON.parse(q.questions_json || '[]').forEach(function (x) {
        if (r[x.id] != null && Number(r[x.id]) < 1) out.push({ key: q.quiz_id + '|' + x.id, title: q.title, date: q.lesson_date || '', q: x });
      });
    });
  return out;
}

function stPractice(me) {
  return practicePool_(me).slice(0, 40).map(function (p) {
    const pub = publicQuestions_([p.q], me.token + '|pm|' + p.key)[0];
    return { key: p.key, title: p.title, date: p.date, q: pub };
  });
}

function stPracticeCheck(me, key, answer) {
  const p = practicePool_(me).filter(function (x) { return x.key === String(key); })[0];
  if (!p) throw new Error('This question is not in your list.');
  const a = cleanAnswers_([p.q], { [p.q.id]: answer })[p.q.id];
  const sc = gradeOne_(p.q, a);
  return { score: Math.round(sc * 100) / 100, right: correctText_(p.q), your: answerText_(p.q, a), explain: p.q.explain || '' };
}

/**
 * Live game (Kahoot-style). Real time runs in Firebase (games/<gid>); this file only:
 *  - opens a game for one quiz (teacher) and gives the host screen the answer key + the class roster with tickets,
 *  - gives each student a ticket proving who they are (HMAC of gid|group|name),
 *  - grades and writes marks when the game ends (same rules as the quiz module: never over an existing mark).
 * Script Property LIVE = {gid, quiz_id, group, date, secs, opened}.
 */
function liveGet_() { try { return JSON.parse(props_().getProperty('LIVE') || 'null'); } catch (e) { return null; } }

function liveSecret_() {
  let s = props_().getProperty('LIVE_SECRET');
  if (!s) { s = Utilities.getUuid() + Utilities.getUuid(); props_().setProperty('LIVE_SECRET', s); }
  return s;
}

function liveTicket_(gid, g, name) {
  const b = Utilities.computeHmacSha256Signature(gid + '|' + g + '|' + name, liveSecret_());
  return b.map(function (x) { return ('0' + (x & 255).toString(16)).slice(-2); }).join('').slice(0, 32);
}

function liveQuestions_(q) {
  return q.questions.filter(function (x) { return x.type === 'mc' || x.type === 'tf'; });
}

function livePayload_(L, q) {
  const qs = liveQuestions_(q).map(function (x) {
    if (x.type === 'tf') return { id: x.id, type: 'tf', prompt: x.prompt, options: ['True', 'False'], correct: x.answer ? 0 : 1, perm: [0, 1], explain: x.explain || '' };
    // same order for the whole game (seeded by gid), so the right answer is not always the first colour
    const perm = shuffle_(x.options.map(function (t, i) { return i; }), rng_(seedOf_(L.gid + '|' + x.id)));
    return { id: x.id, type: x.type, prompt: x.prompt, options: perm.map(function (i) { return x.options[i]; }),
      correct: perm.indexOf(Number(x.answer)), perm: perm, explain: x.explain || '' };
  });
  const roster = readGroup_(L.group, false).students.map(function (s) { return { name: s.name, ticket: liveTicket_(L.gid, L.group, s.name) }; });
  return { gid: L.gid, quiz_id: L.quiz_id, title: q.title, group: L.group, date: L.date, secs: L.secs, questions: qs, roster: roster, now: nowIso_() };
}

function apiLiveState(t) {
  requireTeacher_(t);
  const L = liveGet_();
  if (!L) return null;
  let title = '';
  try { title = getQuiz_(L.quiz_id).title; } catch (e) {}
  return { gid: L.gid, quiz_id: L.quiz_id, group: L.group, title: title, opened: L.opened };
}

function apiLiveOpen(t, id, date, secs) {
  requireTeacher_(t);
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  let L, q;
  try {
    q = getQuiz_(id);
    L = liveGet_();
    if (L && L.quiz_id === String(id)) return livePayload_(L, q);          // resume the running game
    if (L) throw new Error('Another live game is running. Close it first.');
    if (q.status === 'open') throw new Error('This quiz is open in test mode now. Close it first.');
    if (q.status === 'closed') throw new Error('This quiz has already been used. Use "Copy to…" to run it again.');
    if (Object.keys(openMap_()).length) throw new Error('A quiz is open in test mode. Close it first.');
    if (!liveQuestions_(q).length) throw new Error('This quiz has no multiple-choice or true/false questions.');
    if (!/^\d{2}\.\d{2}$/.test(String(date || ''))) date = '';
    const s = Math.round(Number(secs || 20));
    if (!(s >= 5 && s <= 120)) throw new Error('Time per question must be 5–120 seconds.');
    L = { gid: Utilities.getUuid().replace(/-/g, ''), quiz_id: String(id), group: q.group, date: date, secs: s, opened: nowIso_() };
    props_().setProperty('LIVE', JSON.stringify(L));
    log_('teacher', 'live-open', q.group + ' | ' + q.title + ' | ' + s + ' s | ' + (date || 'no date'));
  } finally { lock.releaseLock(); }
  return livePayload_(L, q);
}

function apiLiveCancel(t) {
  requireTeacher_(t);
  const L = liveGet_();
  props_().deleteProperty('LIVE');
  if (L) log_('teacher', 'live-cancel', L.group + ' | ' + L.quiz_id);
  return true;
}

/**
 * results: [{ticket, answers: {qid: value}}] for registered students — value as the grader expects (mc: option index, tf: 1 true / 0 false).
 * report: [{ticket | guest, nick, right, total, points, rank}] for every player (guests too) — saved to _p_live, guests never go to the gradebook.
 */
function apiLiveFinish(t, gid, results, report, opts) {
  requireTeacher_(t);
  const L = liveGet_();
  if (!L || L.gid !== String(gid)) throw new Error('This live game is no longer open.');
  const q = getQuiz_(L.quiz_id);
  const lq = { quiz_id: q.quiz_id, group: q.group, title: q.title, lesson_date: L.date, questions: liveQuestions_(q) };
  // an older host page sends the tapped (shuffled) option index: map it back to the original option here
  const permOf = {};
  if (!(opts && opts.mapped)) lq.questions.forEach(function (x) {
    if (x.type === 'mc') permOf[x.id] = shuffle_(x.options.map(function (o, i) { return i; }), rng_(seedOf_(L.gid + '|' + x.id)));
  });
  (results || []).forEach(function (r) {
    if (!r || !r.answers) return;
    Object.keys(permOf).forEach(function (id) { if (r.answers[id] != null && permOf[id][Number(r.answers[id])] != null) r.answers[id] = permOf[id][Number(r.answers[id])]; });
  });
  const byTicket = {};
  readGroup_(L.group, false).students.forEach(function (s) { byTicket[liveTicket_(L.gid, L.group, s.name)] = s.name; });
  const done = {}, out = { written: 0, conflicts: [], skipped: [], marks: [] };
  (results || []).forEach(function (r) {
    const name = byTicket[String(r && r.ticket)];
    if (!name || done[name]) return;
    done[name] = true;
    if (attemptOf_(q.quiz_id, name)) { out.skipped.push(name + ' (already has a result)'); return; }
    const line = finishAttempt_(lq, name, cleanAnswers_(lq.questions, r.answers || {}), L.opened, 'live');
    if (!line) return;
    out.marks.push({ name: name, score10: Number(line.score10) });
    if (line.written_to_sheet === 'yes') out.written++; else out.conflicts.push(name + ': ' + line.note);
  });
  // report of everyone who played (students + guests)
  const markOf = {}, noteOf = {};
  out.marks.forEach(function (m) { markOf[m.name] = m.score10; });
  out.conflicts.forEach(function (c) { const i = c.indexOf(': '); noteOf[c.slice(0, i)] = c.slice(i + 2); });
  out.skipped.forEach(function (c) { noteOf[c.replace(/ \(already has a result\)$/, '')] = 'already had a result'; });
  const now = nowIso_(), rows = [], seen = {};
  (report || []).slice(0, 300).forEach(function (r) {
    const reg = r && r.ticket ? byTicket[String(r.ticket)] : null;
    if (r && r.ticket && !reg) return;
    const name = reg || String((r && r.guest) || '').trim().slice(0, 60);
    if (!name) return;
    const k = (reg ? 's|' : 'g|') + name + '|' + String(r.nick || '');
    if (seen[k]) return; seen[k] = 1;
    rows.push([now, q.quiz_id, q.group, q.title, L.date || '', name, String(r.nick || '').slice(0, 20), reg ? 'student' : 'guest',
      String(Number(r.right) || 0), String(Number(r.total) || 0), String(Number(r.points) || 0), String(Number(r.rank) || 0),
      reg && markOf[name] != null ? String(markOf[name]) : '', reg ? (noteOf[name] || (markOf[name] != null && L.date ? 'written' : (L.date ? '' : 'practice (no date)'))) : 'guest: not in gradebook']);
  });
  if (rows.length) { const sh = pSheet_('_p_live'); sh.getRange(sh.getLastRow() + 1, 1, rows.length, rows[0].length).setNumberFormat('@').setValues(rows); SpreadsheetApp.flush(); tableChanged_('_p_live'); }
  out.reported = rows.length;
  try { const js = liveStatsJson_(opts); if (js) props_().setProperty('LIVESTAT_' + q.quiz_id, js); } catch (e) { log_('teacher', 'live-stats-error', String(e)); }
  patchQuiz_(q.quiz_id, { status: 'closed', opened_at: L.opened, closes_at: nowIso_(), lesson_date: L.date, duration_min: q.duration_min });
  props_().deleteProperty('LIVE');
  log_('teacher', 'live-finish', L.group + ' | ' + q.title + ' | ' + out.marks.length + ' players | ' + out.written + ' written');
  return out;
}

/** Per-question statistics, teams and class mission of a finished game (Script Property LIVESTAT_<quiz_id>, max ~9 KB). */
function liveStatsJson_(o) {
  if (!o || !Array.isArray(o.qstats)) return '';
  const str = function (v, n) { return String(v == null ? '' : v).slice(0, n); }, num = function (v) { return Math.max(0, Math.round(Number(v) || 0)); };
  const mk = function (pl, ol) {
    return JSON.stringify({ mode: str(o.mode, 12), scoring: str(o.scoring, 12),
      qstats: o.qstats.slice(0, 60).map(function (x) { return { id: str(x.id, 20), prompt: str(x.prompt, pl), options: ol ? (x.options || []).slice(0, 4).map(function (t) { return str(t, ol); }) : [],
        correct: num(x.correct), counts: (x.counts || []).slice(0, 4).map(num), answered: num(x.answered), right: num(x.right), players: num(x.players) }; }),
      teams: Array.isArray(o.teams) ? o.teams.slice(0, 6).map(function (t) { return { name: str(t.name, 20), score: num(t.score), rank: num(t.rank), members: (t.members || []).slice(0, 40).map(function (m) { return str(m, 20); }) }; }) : null,
      mission: o.mission ? { fuel: num(o.mission.fuel), goal: num(o.mission.goal), players: num(o.mission.players) } : null });
  };
  const tries = [[90, 30], [70, 20], [50, 14], [40, 0]];
  for (let i = 0; i < tries.length; i++) { const js = mk(tries[i][0], tries[i][1]); if (js.length < 8800) return js; }
  return '';
}

/** Students' feedback after the game (stars 1–5, learned yes/no, feeling 0 😃 1 😐 2 😞). Script Property LIVEFB_<quiz_id>. */
function apiLiveFeedback(t, id, rows) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  let out = (rows || []).slice(0, 120).map(function (r) {
    const v = { name: String((r && r.name) || '').slice(0, 40), nick: String((r && r.nick) || '').slice(0, 20), r: Math.min(5, Math.max(1, Math.round(Number(r && r.r) || 0))) };
    if (r && r.guest) v.guest = true;
    if (r && typeof r.l === 'boolean') v.l = r.l;
    if (r && [0, 1, 2].indexOf(r.f) >= 0) v.f = r.f;
    return v;
  }).filter(function (v) { return v.name && v.r; });
  let js = JSON.stringify(out);
  while (js.length > 8800 && out.length) { out = out.slice(0, out.length - 5); js = JSON.stringify(out); }
  props_().setProperty('LIVEFB_' + q.quiz_id, js);
  return out.length;
}

/* ---------- student ---------- */
function liveFor_(g) { const L = liveGet_(); return L && L.group === String(g) ? L : null; }

function stLiveJoin(me) {
  const L = liveFor_(me.group);
  if (!L) throw new Error('There is no live game for your group now.');
  let title = '';
  try { title = getQuiz_(L.quiz_id).title; } catch (e) {}
