}

/** Report of a finished live game: everyone who played (students and guests) + students of the group who did not join. */
function apiLiveReport(t, id) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  const rows = readTable_('_p_live').filter(function (r) { return r.quiz_id === String(id); });
  const played = {};
  rows.forEach(function (r) { if (r.kind === 'student') played[r.name] = 1; });
  const missing = readGroup_(q.group, false).students.map(function (s) { return s.name; }).filter(function (n) { return !played[n]; });
  return { title: q.title, group: q.group, date: q.lesson_date, time: rows.length ? rows[0].time : '',
    rows: rows.map(function (r) { return { name: r.name, nick: r.nick, kind: r.kind, right: Number(r.right), total: Number(r.total), points: Number(r.points), rank: Number(r.rank), mark: r.mark, note: r.note }; })
      .sort(function (a, b) { return a.rank - b.rank; }),
    missing: missing, stats: liveProp_('LIVESTAT_' + q.quiz_id), feedback: liveProp_('LIVEFB_' + q.quiz_id) };
}
function liveProp_(k) { try { return JSON.parse(props_().getProperty(k) || 'null'); } catch (e) { return null; } }

/**
 * Personal tests (12.11.2026): one test for ONE student, made by Claude/teacher in _p_personal.
 * kind "makeup": score out of 10 is written into every target date column where the student has 0 / nb / empty.
 * kind "on":     score out of max_score (20) goes to the target column (e.g. "Oraliq N (20)") only if it is HIGHER.
 * The student takes it with the normal quiz screen (ids start with "p_"). Questions keep an optional weight "w".
 * target_json: {"dates":["16.09",...]} or {"col":"Oraliq N (20)","rule":"max"}.  show_score: "yes" / "no".
 */

function pRows_() { return readTable_('_p_personal'); }
/** questions_json may be "src:<key>": the questions then live in PersonalData.gs (pushed with clasp, never public). */
function pQuestions_(r) {
  const s = String(r.questions_json || '');
  if (/^src:/.test(s)) { const k = s.slice(4).trim(); if (typeof PERSONAL_DATA === 'undefined' || !PERSONAL_DATA[k]) throw new Error('Questions not found: ' + k); return PERSONAL_DATA[k]; }
  return JSON.parse(s || '[]');
}
function pRow_(id) {
  const r = pRows_().filter(function (x) { return x.id === String(id); })[0];
  if (!r) throw new Error('This test was not found.');
  r.questions = pQuestions_(r);
  r.target = JSON.parse(r.target_json || '{}');
  return r;
}
function pPatch_(row, patch) {
  const sh = pSheet_('_p_personal');
  const H = P_SHEETS._p_personal;
  Object.keys(patch).forEach(function (k) {
    const c = H.indexOf(k); if (c < 0) return;
    sh.getRange(row._row, c + 1).setValue(patch[k]);
  });
  SpreadsheetApp.flush();
}
function pDeadlinePassed_(r) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})(?: (\d{1,2}):(\d{2}))?$/.exec(String(r.deadline || ''));
  if (!m) return false;
  const d = new Date(+m[3], +m[2] - 1, +m[1], m[4] ? +m[4] : 23, m[5] ? +m[5] : 59, 59);
  return Date.now() > d.getTime();
}
function pMine_(me, r) { return r.group === String(me.group) && r.full_name === me.name; }

/** For stHome: the tests waiting for this student. */
function personalFor_(me) {
  return pRows_().filter(function (r) {
    return pMine_(me, r) && (r.status === 'ready' || r.status === 'started') && !pDeadlinePassed_(r);
  }).map(function (r) {
    let n = 0; try { n = pQuestions_(r).length; } catch (e) {}
    return { id: r.id, title: r.title, count: n, minutes: Number(r.duration_min || 30), deadline: r.deadline, state: r.status === 'started' ? 'working' : 'new' };
  });
}

function pStart_(me, id) {
  let r = pRow_(id);
  if (!pMine_(me, r)) throw new Error('This test is not for you.');
  if (r.status === 'done') throw new Error('You have already done this test.');
  if (r.status !== 'ready' && r.status !== 'started') throw new Error('This test is closed.');
  if (r.status === 'ready' && pDeadlinePassed_(r)) throw new Error('The deadline for this test has passed.');
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    r = pRow_(id);
    if (r.status === 'ready') {
      const now = new Date(), closes = new Date(now.getTime() + Number(r.duration_min || 30) * 60000);
      pPatch_(r, { status: 'started', started_at: now.toISOString(), closes_at: closes.toISOString() });
      r.status = 'started'; r.started_at = now.toISOString(); r.closes_at = closes.toISOString();
      log_('personal', 'start', r.group + ' | ' + r.full_name + ' | ' + r.title);
    }
  } finally { lock.releaseLock(); }
  if (Date.now() > new Date(r.closes_at).getTime() + GRACE_MS) {
    pFinish_(r, null, 'time ran out');
    throw new Error('Time is up for this test. Your saved answers were sent.');
  }
  const saved = CacheService.getScriptCache().get(ansKey_(id, me.name));
  return { quiz_id: id, title: r.title, unit: '', closes_at: r.closes_at, now: nowIso_(), personal: true,
    questions: publicQuestions_(r.questions, me.token + '|' + id), saved: saved ? JSON.parse(saved) : {} };
}

function pSave_(me, id, answers) {
  const r = pRow_(id);
  if (!pMine_(me, r) || r.status !== 'started') return { ok: false };
  if (Date.now() > new Date(r.closes_at).getTime() + GRACE_MS) return { ok: false, late: true };
  const s = JSON.stringify(answers || {});
  if (s.length > 90000) throw new Error('Answers are too long.');
  CacheService.getScriptCache().put(ansKey_(id, me.name), s, 21600);
  return { ok: true, closes: r.closes_at };
}

function pSubmit_(me, id, answers) {
  let r = pRow_(id);
  if (!pMine_(me, r)) throw new Error('This test is not for you.');
  if (r.status === 'started') {
    const late = Date.now() > new Date(r.closes_at).getTime() + GRACE_MS;
    let ans = cleanAnswers_(r.questions, answers);
    if (late) { const sv = CacheService.getScriptCache().get(ansKey_(id, me.name)); ans = cleanAnswers_(r.questions, sv ? JSON.parse(sv) : {}); }
    pFinish_(r, ans, late ? 'late: graded on the answers saved in time' : '');
    r = pRow_(id);
  }
  if (r.status !== 'done') throw new Error('Start the test first.');
  const res = (JSON.parse(r.answers_json || '{}').r) || {};
  const right = Object.keys(res).filter(function (k) { return res[k] >= 1; }).length;
  const show = String(r.show_score || 'yes') !== 'no';
  return { score10: show ? Number(r.score) : null, max: Number(r.max_score || 10), right: show ? right : null, total: r.questions.length, personal: true, hidden: !show };
}

/** Grades and writes the mark. answers == null → take the autosaved ones. */
function pFinish_(r, answers, note) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    r = pRow_(r.id);
    if (r.status !== 'started') return;
    if (answers == null) { const sv = CacheService.getScriptCache().get(ansKey_(r.id, r.full_name)); answers = cleanAnswers_(r.questions, sv ? JSON.parse(sv) : {}); }
    const res = {}; let got = 0, all = 0;
    r.questions.forEach(function (q) {
      const w = Number(q.w || 1), sc = gradeOne_(q, answers[q.id]);
      res[q.id] = Math.round(sc * 100) / 100; got += sc * w; all += w;
    });
    const max = Number(r.max_score || 10);
    const score = round1_(all ? got / all * max : 0);
    const w = pWriteMark_(r, score);
    pPatch_(r, { status: 'done', submitted_at: nowIso_(), answers_json: JSON.stringify({ a: answers, r: res }),
      score_raw: String(Math.round(got * 100) / 100) + '/' + all, score: String(score), written: w, note: note || '' });
    CacheService.getScriptCache().remove(ansKey_(r.id, r.full_name));
    log_('personal', 'submit', r.group + ' | ' + r.full_name + ' | ' + r.title + ' | ' + score + '/' + max + ' | ' + w);
  } finally { lock.releaseLock(); }
}

function pWriteMark_(r, score) {
  const d = readGroup_(r.group, true);
  const st = d.students.filter(function (s) { return s.name === r.full_name; })[0];
  if (!st) return 'student not in sheet';
  const sh = groupSheet_(r.group), t = r.target || {}, out = [];
  if (r.kind === 'makeup') {
    (t.dates || []).forEach(function (h) {
      const col = d.cols.filter(function (c) { return c.kind === 'day' && c.h === h; })[0];
      if (!col) { out.push(h + ': no column'); return; }
      const cell = sh.getRange(st.row, col.c);
      const old = String(cell.getDisplayValue()).trim();
      if (old === '' || isAbsent_(old)) { cell.setValue(score); out.push(h + ': ' + (old || '·') + '→' + score); }
      else out.push(h + ': kept ' + old);
    });
  } else if (r.kind === 'on') {
    const col = d.cols.filter(function (c) { return c.h === t.col; })[0];
    if (!col) return 'no column ' + t.col;
    const cell = sh.getRange(st.row, col.c);
    if (cell.getFormula()) return 'formula cell';
    const old = Number(String(cell.getDisplayValue()).replace(',', '.'));
    const has = String(cell.getDisplayValue()).trim() !== '' && isFinite(old);
    if (t.rule === 'replace' || !has || score > old) { cell.setValue(score); out.push(t.col + ': ' + (has ? old : '·') + '→' + score); }
    else out.push(t.col + ': kept ' + old + ' (new ' + score + ')');
  } else return 'unknown kind';
  SpreadsheetApp.flush(); clearGroupCache_(r.group);
  return out.join('; ');
}

/** tick: close started tests whose time ran out (graded on saved answers). */
function closeExpiredPersonal_() {
  const sh = ss_().getSheetByName('_p_personal'); if (!sh) return;
  pRows_().filter(function (r) { return r.status === 'started' && Date.now() > new Date(r.closes_at).getTime() + GRACE_MS; })
    .forEach(function (r) { try { pFinish_(pRow_(r.id), null, 'auto-submitted when time ran out'); } catch (e) { log_('personal', 'close-error', r.id + ': ' + e.message); } });
}

/** Teacher/Claude check in the editor: validates every ready row (no writes). */
function personalCheck() {
  const out = pRows_().map(function (r) {
    try { const qs = validateQuestions_(pQuestions_(r)); return r.id + ' ok ' + qs.length + ' q'; }
    catch (e) { return r.id + ' ERROR ' + e.message; }
  });
  Logger.log(out.join('\n')); return out;
}

/**
 * In-class quizzes: draft → ready → open → closed.
 * Time is kept on the server (closes_at). Correct answers never go to a student's browser
 * while a quiz is open; grading happens only here.
 */
const QUIZ_TYPES = ['mc', 'gap', 'match', 'order', 'tf'];
const GRACE_MS = 30000;

function nowIso_() { return new Date().toISOString(); }

/* ---------- storage ---------- */

function quizRows_() { return readTable_('_p_quizzes'); }
function quizRowsC_() { return readTableC_('_p_quizzes'); }

function getQuiz_(id) {
  const q = quizRowsC_().filter(function (r) { return r.quiz_id === String(id); })[0];
  if (!q) throw new Error('Quiz not found.');
  q.questions = JSON.parse(q.questions_json || '[]');
  return q;
}

function patchQuiz_(id, patch) {
  const obj = { quiz_id: id };
  Object.keys(patch).forEach(function (k) { obj[k] = k === 'questions' ? undefined : patch[k]; });
  if (patch.questions) obj.questions_json = JSON.stringify(patch.questions);
  upsertRow_('_p_quizzes', function (r) { return r.quiz_id === id; }, obj);
}

function jprop_(k) { try { return JSON.parse(props_().getProperty(k) || '{}'); } catch (e) { return {}; } }
function setJprop_(k, v) { if (Object.keys(v).length) props_().setProperty(k, JSON.stringify(v)); else props_().deleteProperty(k); }
function openMap_() { return jprop_('OPEN_QUIZZES'); }            // {quiz_id: {group, closes}}
function startedMap_(id) { return jprop_('QS_' + id); }           // {full_name: startedIso}
function ansKey_(id, name) { return 'ans_' + id + '_' + seedOf_(name); }

function attemptOf_(id, name) {
  return readTableC_('_p_attempts').filter(function (r) { return r.quiz_id === String(id) && r.full_name === name && r.submitted_at; })[0] || null;
}

/* ---------- question format ---------- */

function norm_(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/[’‘`´ʼ]/g, "'").replace(/\s+/g, ' ').trim().replace(/[.!?,;:]+$/, '').trim();
}

function validateQuestions_(qs) {
  if (typeof qs === 'string') {
    try { qs = JSON.parse(qs); } catch (e) { throw new Error('Questions are not valid JSON (' + e.message + ').'); }
  }
  if (!Array.isArray(qs) || !qs.length) throw new Error('Add at least one question.');
  if (qs.length > 40) throw new Error('At most 40 questions in one quiz.');
  const ids = {};
  return qs.map(function (q, i) {
    const n = 'Question ' + (i + 1) + ': ';
    const type = String(q.type || '').toLowerCase();
    if (QUIZ_TYPES.indexOf(type) < 0) throw new Error(n + 'type must be mc, gap, match, order or tf.');
    const out = { id: String(q.id || ('q' + (i + 1))), type: type, prompt: String(q.prompt || '').trim(), explain: String(q.explain || '').trim() };
    if (ids[out.id]) out.id = 'q' + (i + 1) + '_' + i;
    ids[out.id] = 1;
    if (type === 'mc') {
      const opts = (q.options || []).map(function (o) { return String(o).trim(); });
      if (opts.length < 2 || opts.length > 6) throw new Error(n + 'give 2–6 options.');
      if (opts.some(function (o) { return !o; })) throw new Error(n + 'an option is empty.');
      const low = opts.map(function (o) { return o.toLowerCase(); });
      if (low.some(function (o, j) { return low.indexOf(o) !== j; })) throw new Error(n + 'two options are the same.');
      let a = q.answer;
      a = (typeof a === 'string' && !/^\d+$/.test(a)) ? opts.indexOf(a.trim()) : Number(a);
      if (!(a >= 0 && a < opts.length)) throw new Error(n + 'answer must be the number (0–' + (opts.length - 1) + ') or the text of the right option.');
      out.options = opts; out.answer = a;
      if (!out.prompt) throw new Error(n + 'the question text is empty.');
    } else if (type === 'tf') {
      const s = String(q.answer).toLowerCase();
      if (['true', 'false'].indexOf(s) < 0) throw new Error(n + 'answer must be true or false.');
      out.answer = s === 'true';
      if (!out.prompt) throw new Error(n + 'the statement is empty.');
    } else if (type === 'gap') {
      const acc = [];
      [].concat(q.answer != null && q.answer !== '' ? [q.answer] : [], q.accept || []).forEach(function (x) {
        x = String(x).trim();
        if (x && acc.map(norm_).indexOf(norm_(x)) < 0) acc.push(x);
      });
      if (!acc.length) throw new Error(n + 'give the right answer (answer or accept).');
      if (!out.prompt) throw new Error(n + 'the sentence is empty.');
      out.accept = acc;
    } else if (type === 'match') {
      const pairs = (q.pairs || []).map(function (p) { return [String(p[0] || '').trim(), String(p[1] || '').trim()]; });
      if (pairs.length < 2 || pairs.length > 8) throw new Error(n + 'give 2–8 pairs.');
      if (pairs.some(function (p) { return !p[0] || !p[1]; })) throw new Error(n + 'a pair is empty.');
      const r = pairs.map(function (p) { return p[1].toLowerCase(); });
      if (r.some(function (x, j) { return r.indexOf(x) !== j; })) throw new Error(n + 'two right-hand items are the same.');
      out.pairs = pairs;
      if (!out.prompt) out.prompt = 'Match the items.';
    } else if (type === 'order') {
      const items = (q.items || []).map(function (x) { return String(x).trim(); });
      if (items.length < 2 || items.length > 10) throw new Error(n + 'give 2–10 items in the right order.');
      if (items.some(function (x) { return !x; })) throw new Error(n + 'an item is empty.');
      out.items = items;
      if (!out.prompt) out.prompt = 'Put the items in the correct order.';
    }
    return out;
  });
}

/* ---------- shuffling (seeded: the same student sees the same order after a reload) ---------- */

function seedOf_(s) {
  let h = 2166136261;
  s = String(s);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function rng_(seed) {
  let a = seed;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffle_(arr, r) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); const x = a[i]; a[i] = a[j]; a[j] = x; }
  return a;
}

/** What the browser gets: no answers, no accept lists, no pairs. */
function publicQuestions_(qs, seedStr) {
  const r = rng_(seedOf_(seedStr));
  const idx = function (arr) { return arr.map(function (t, i) { return { i: i, t: t }; }); };
  return shuffle_(qs, r).map(function (q) {
    const o = { id: q.id, type: q.type, prompt: q.prompt };
    if (q.type === 'mc') o.options = shuffle_(idx(q.options), r);
    if (q.type === 'tf') o.options = [{ i: 1, t: 'True' }, { i: 0, t: 'False' }];
    if (q.type === 'match') {
      o.left = shuffle_(idx(q.pairs.map(function (p) { return p[0]; })), r);
      o.right = shuffle_(idx(q.pairs.map(function (p) { return p[1]; })), r);
    }
    if (q.type === 'order') {
      let s = idx(q.items);
      for (let k = 0; k < 8; k++) { s = shuffle_(idx(q.items), r); if (s.some(function (x, j) { return x.i !== j; })) break; }
      o.items = s;
    }
    return o;
  });
}

/* ---------- grading ---------- */

/** 0..1 for one question. Match and order give part marks (share of right pairs). */
function gradeOne_(q, a) {
  if (a == null || a === '') return 0;
  if (q.type === 'mc') return Number(a) === q.answer ? 1 : 0;
  if (q.type === 'tf') return (Number(a) === 1) === q.answer ? 1 : 0;
  if (q.type === 'gap') return q.accept.map(norm_).indexOf(norm_(a)) >= 0 ? 1 : 0;
  if (q.type === 'match') {
    if (typeof a !== 'object') return 0;
    let k = 0;
    q.pairs.forEach(function (p, i) { if (a[i] != null && a[i] !== '' && Number(a[i]) === i) k++; });
    return k / q.pairs.length;
  }
  if (q.type === 'order') {
    if (!Array.isArray(a) || a.length !== q.items.length) return 0;
    let k = 0;
    for (let i = 0; i < a.length - 1; i++) if (Number(a[i + 1]) === Number(a[i]) + 1) k++;
    if (a.length === 1) return Number(a[0]) === 0 ? 1 : 0;
    return k / (a.length - 1);
  }
  return 0;
}

function correctText_(q) {
  if (q.type === 'mc') return q.options[q.answer];
  if (q.type === 'tf') return q.answer ? 'True' : 'False';
  if (q.type === 'gap') return q.accept.join(' / ');
  if (q.type === 'match') return q.pairs.map(function (p) { return p[0] + ' → ' + p[1]; }).join('; ');
  if (q.type === 'order') return q.items.join(' / ');
  return '';
}

function answerText_(q, a) {
  if (a == null || a === '') return '—';
  if (q.type === 'mc') return q.options[Number(a)] || '—';
  if (q.type === 'tf') return Number(a) === 1 ? 'True' : 'False';
  if (q.type === 'gap') return String(a);
  if (q.type === 'match') return q.pairs.map(function (p, i) {
    const j = a[i]; return p[0] + ' → ' + (j != null && j !== '' && q.pairs[Number(j)] ? q.pairs[Number(j)][1] : '—');
  }).join('; ');
  if (q.type === 'order') return Array.isArray(a) ? a.map(function (i) { return q.items[Number(i)]; }).join(' / ') : '—';
  return '';
}

function cleanAnswers_(qs, answers) {
  const out = {};
  if (!answers || typeof answers !== 'object') return out;
  qs.forEach(function (q) {
    const a = answers[q.id];
    if (a == null) return;
    if (q.type === 'gap') out[q.id] = String(a).slice(0, 200);
    else if (q.type === 'mc' || q.type === 'tf') out[q.id] = Number(a);
    else if (q.type === 'order' && Array.isArray(a)) out[q.id] = a.slice(0, 12).map(Number);
    else if (q.type === 'match' && typeof a === 'object') { const m = {}; Object.keys(a).slice(0, 12).forEach(function (k) { m[k] = a[k] === '' ? '' : Number(a[k]); }); out[q.id] = m; }
  });
  return out;
}

/* ---------- gradebook ---------- */

function dayCol_(g, ddmm) {
  return readGroup_(g, false).cols.filter(function (c) { return c.kind === 'day' && c.h === ddmm; })[0] || null;
}

/** Caller holds the script lock. Never writes over a mark that is already there. */
function writeQuizMark_(q, name, score) {
  const col = q.lesson_date ? dayCol_(q.group, q.lesson_date) : null;
  if (!col) return 'no date column';
  let d = readGroup_(q.group, false);
  let st = d.students.filter(function (s) { return s.name === name; })[0];
  const sh = groupSheet_(q.group);
  if (!st || String(sh.getRange(st.row, NAME_COL).getDisplayValue()).trim() !== name) {
    d = readGroup_(q.group, true);
    st = d.students.filter(function (s) { return s.name === name; })[0];
    if (!st) return 'student not in sheet';
  }
  const cell = sh.getRange(st.row, col.c);
  if (cell.getFormula()) return 'formula cell';
  const old = String(cell.getDisplayValue()).trim();
  if (old !== '') return 'conflict: cell already has ' + old;
  cell.setValue(score);
  SpreadsheetApp.flush();
  clearGroupCache_(q.group);
  log_('quiz', 'set', q.group + ' | ' + name + ' | ' + col.h + ' |  -> ' + score + ' | ' + q.title);
  return 'written';
}

function finishAttempt_(q, name, answers, startedAt, note) {
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    if (attemptOf_(q.quiz_id, name)) return null;
    const res = {};
    let raw = 0;
    q.questions.forEach(function (x) {
      const sc = gradeOne_(x, answers ? answers[x.id] : null);
      res[x.id] = Math.round(sc * 100) / 100; raw += sc;
    });
    let s10 = round1_(raw / q.questions.length * 10);
    if (String(getSetting_('minAttendScore', 'off')) === 'on' && s10 < 5) s10 = 5;
    const w = writeQuizMark_(q, name, s10);
    const line = {
      quiz_id: q.quiz_id, group: q.group, full_name: name, started_at: startedAt || '', submitted_at: nowIso_(),
      answers_json: JSON.stringify({ a: answers || {}, r: res }), score_raw: String(Math.round(raw * 100) / 100),
      score10: String(s10), written_to_sheet: w === 'written' ? 'yes' : 'no',
      note: [w === 'written' ? '' : w, note || ''].filter(String).join('; ')
    };
    pSheet_('_p_attempts').appendRow(P_SHEETS._p_attempts.map(function (h) { return line[h]; }));
    SpreadsheetApp.flush(); tableChanged_('_p_attempts');
    const m = startedMap_(q.quiz_id); delete m[name]; setJprop_('QS_' + q.quiz_id, m);
    log_('quiz', 'submit', q.group + ' | ' + name + ' | ' + q.title + ' | ' + s10 + ' | ' + w);
    return line;
  } finally { lock.releaseLock(); }
}

/* ---------- open / close ---------- */

function refreshQuiz_(q) {
  if (q.status === 'open' && Date.now() > new Date(q.closes_at).getTime() + GRACE_MS) {
    finalizeQuiz_(q.quiz_id);
    return getQuiz_(q.quiz_id);
  }
  return q;
}

function closeExpiredQuizzes_() {
  const m = openMap_(), now = Date.now();
  Object.keys(m).forEach(function (id) {
    if (now > new Date(m[id].closes).getTime() + GRACE_MS) finalizeQuiz_(id);
  });
}

/** Grades everyone who started but did not press Finish (answers saved while working), then closes. */
function finalizeQuiz_(id) {
  let q;
  try { q = getQuiz_(id); } catch (e) { q = null; }
  if (q && q.status === 'open') {
    const sm = startedMap_(id), cache = CacheService.getScriptCache();
    Object.keys(sm).forEach(function (name) {
      const saved = cache.get(ansKey_(id, name));
      finishAttempt_(q, name, saved ? JSON.parse(saved) : {}, sm[name], 'auto-submitted when time ran out');
    });
    patchQuiz_(id, { status: 'closed' });
    log_('quiz', 'closed', q.group + ' | ' + q.title);
  }
  const m = openMap_(); delete m[id]; setJprop_('OPEN_QUIZZES', m);
  props_().deleteProperty('QS_' + id);
}

function openQuizFor_(g) {
  const m = openMap_();
  const id = Object.keys(m).filter(function (k) { return m[k].group === String(g); })[0];
  if (!id) return null;
  const q = refreshQuiz_(getQuiz_(id));
  return q.status === 'open' ? q : null;
}

/* ---------- student side ---------- */

function stQuizStart(me, id) {
  if (/^p_/.test(String(id))) return pStart_(me, id);
  const q = refreshQuiz_(getQuiz_(id));
  if (q.group !== me.group) throw new Error('This quiz is not for your group.');
  if (q.status !== 'open') throw new Error('This quiz is closed.');
  if (attemptOf_(id, me.name)) throw new Error('You have already done this quiz. Only one attempt is allowed.');
  if (Date.now() > new Date(q.closes_at).getTime()) throw new Error('Time is up for this quiz.');
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const sm = startedMap_(id);
    if (!sm[me.name]) { sm[me.name] = nowIso_(); setJprop_('QS_' + id, sm); log_('quiz', 'start', q.group + ' | ' + me.name + ' | ' + q.title); }
  } finally { lock.releaseLock(); }
  const saved = CacheService.getScriptCache().get(ansKey_(id, me.name));
  const om = openMap_()[id];   // the open-quiz map is what the server enforces
  return { quiz_id: id, title: q.title, unit: q.unit, closes_at: (om && om.closes) || q.closes_at, now: nowIso_(),
    questions: publicQuestions_(q.questions, me.token + '|' + id), saved: saved ? JSON.parse(saved) : {} };
}

/** Autosave while working (cache only, no sheet writes: fast for a whole class). */
function stQuizSave(me, id, answers) {
  if (/^p_/.test(String(id))) return pSave_(me, id, answers);
  const m = openMap_()[id];
  if (!m || m.group !== me.group) return { ok: false };
  if (Date.now() > new Date(m.closes).getTime() + GRACE_MS) return { ok: false, late: true };
  if (!startedMap_(id)[me.name]) return { ok: false };
  const s = JSON.stringify(answers || {});
  if (s.length > 90000) throw new Error('Answers are too long.');
  CacheService.getScriptCache().put(ansKey_(id, me.name), s, 21600);
  return { ok: true, closes: m.closes };
}

function stQuizSubmit(me, id, answers) {
  if (/^p_/.test(String(id))) return pSubmit_(me, id, answers);
  const q = getQuiz_(id);
  if (q.group !== me.group) throw new Error('This quiz is not for your group.');
  let att = attemptOf_(id, me.name);
  if (!att) {
    const sm = startedMap_(id);
    if (!sm[me.name]) throw new Error(q.status === 'open' ? 'Start the quiz first.' : 'This quiz is closed.');
    const late = q.status !== 'open' || Date.now() > new Date(q.closes_at).getTime() + GRACE_MS;
    let ans = cleanAnswers_(q.questions, answers);
    if (late) { const saved = CacheService.getScriptCache().get(ansKey_(id, me.name)); ans = cleanAnswers_(q.questions, saved ? JSON.parse(saved) : {}); }
    finishAttempt_(q, me.name, ans, sm[me.name], late ? 'late: graded on the answers saved in time' : '');
    att = attemptOf_(id, me.name);
  }
  const r = (JSON.parse(att.answers_json || '{}').r) || {};
  return { score10: Number(att.score10), right: Object.keys(r).filter(function (k) { return r[k] >= 1; }).length, total: q.questions.length };
}

function stQuizReview(me, id) {
  const q = refreshQuiz_(getQuiz_(id));
  if (q.group !== me.group) throw new Error('This quiz is not for your group.');
  if (q.status !== 'closed') throw new Error('You can see the answers when the quiz is closed.');
  const att = attemptOf_(id, me.name);
  const parsed = att ? JSON.parse(att.answers_json || '{}') : { a: {}, r: {} };
  const isLive = att && /live/.test(att.note || '');
  const shown = isLive ? q.questions.filter(function (x) { return parsed.r && parsed.r[x.id] != null; }) : q.questions;
  return {
    title: q.title, unit: q.unit, date: q.lesson_date, missed: !att, score10: att ? Number(att.score10) : null,
    items: shown.map(function (x) {
      const sc = parsed.r[x.id];
      return { type: x.type, prompt: x.prompt, your: answerText_(x, parsed.a[x.id]), right: correctText_(x),
        score: sc == null ? 0 : sc, explain: x.explain };
    })
  };
}

/* ---------- teacher side ---------- */

function quizMeta_(q, atts) {
  return { quiz_id: q.quiz_id, group: q.group, unit: q.unit, title: q.title, duration_min: Number(q.duration_min || 10),
    status: q.status, opened_at: q.opened_at, closes_at: q.closes_at, lesson_date: q.lesson_date, created_at: q.created_at,
    count: (q.questions || JSON.parse(q.questions_json || '[]')).length,
    done: atts ? atts.filter(function (a) { return a.quiz_id === q.quiz_id; }).length : null };
}

function apiQuizzes(t, g) {
  requireTeacher_(t);
  closeExpiredQuizzes_();
  const atts = readTable_('_p_attempts');
  const all = quizRows_();
  const order = { open: 0, ready: 1, draft: 2, closed: 3 };
  const lived = {}; readTable_('_p_live').forEach(function (r) { lived[r.quiz_id] = 1; });
  const list = all.filter(function (q) { return q.group === String(g); }).map(function (q) { const m = quizMeta_(q, atts); m.live = !!lived[q.quiz_id]; return m; })
    .sort(function (a, b) {
      if (order[a.status] !== order[b.status]) return order[a.status] - order[b.status];
      if (a.status === 'closed') return String(b.opened_at || b.created_at).localeCompare(String(a.opened_at || a.created_at));
      const da = ddmm_(a.lesson_date) || 9999, db = ddmm_(b.lesson_date) || 9999;   // planned quizzes in lesson order
      return (da - db) || String(a.created_at).localeCompare(String(b.created_at));
    });
  const openNow = all.filter(function (q) { return q.status === 'open'; }).map(function (q) { return quizMeta_(q, atts); });
  return { list: list, openNow: openNow, now: nowIso_() };
}

function apiQuiz(t, id) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  const m = quizMeta_(q, null); m.questions = q.questions;
  return m;
}

function apiSaveQuiz(t, o) {
  requireTeacher_(t);
  ensureSheets_();
  if (!o || !String(o.title || '').trim()) throw new Error('Give the quiz a title.');
  if (listGroups_().indexOf(String(o.group)) < 0) throw new Error('Unknown group: ' + o.group);
  const qs = validateQuestions_(o.questions);
  const dur = Math.round(Number(o.duration_min || 10));
  if (!(dur >= 1 && dur <= 60)) throw new Error('Time must be 1–60 minutes.');
  let old = null;
  if (o.quiz_id) {
    old = getQuiz_(o.quiz_id);
    if (old.status === 'open' || old.status === 'closed') throw new Error('This quiz has already been used. Duplicate it to change it.');
  }
  const id = o.quiz_id || ('q' + Utilities.formatDate(new Date(), 'Asia/Tashkent', 'yyMMdd') + newToken_().slice(0, 4));
  const obj = { quiz_id: id, group: String(o.group), unit: String(o.unit || ''), title: String(o.title).trim(), duration_min: String(dur),
    status: o.status === 'draft' ? 'draft' : 'ready', opened_at: '', closes_at: '', lesson_date: '',
    created_at: old ? old.created_at : nowIso_(), questions_json: JSON.stringify(qs) };
  upsertRow_('_p_quizzes', function (r) { return r.quiz_id === id; }, obj);
  log_('teacher', 'quiz-save', obj.group + ' | ' + obj.title + ' | ' + qs.length + ' q');
  return apiQuiz(t, id);
}

function apiCopyQuiz(t, id, g) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  return apiSaveQuiz(t, { group: g || q.group, unit: q.unit, title: q.title, duration_min: q.duration_min, questions: q.questions, status: 'ready' });
}

function apiDeleteQuiz(t, id) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  if (q.status === 'open') throw new Error('Close the quiz first.');
  if (readTable_('_p_attempts').some(function (a) { return a.quiz_id === id; })) throw new Error('This quiz has results, so it is kept.');
  const fresh = quizRows_().filter(function (r) { return r.quiz_id === String(id); })[0];
  if (!fresh) throw new Error('Quiz not found.');
  pSheet_('_p_quizzes').deleteRow(fresh._row);
  SpreadsheetApp.flush(); tableChanged_('_p_quizzes');
  log_('teacher', 'quiz-delete', q.group + ' | ' + q.title);
  return true;
}

/** Before "Start": lesson dates and how many marks are already on the chosen date. */
function apiStartCheck(t, id, date) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  const d = readGroup_(q.group, false);
  const days = d.cols.filter(function (c) { return c.kind === 'day'; });
  const today = Utilities.formatDate(new Date(), 'Asia/Tashkent', 'dd.MM');
  const has = function (x) { return !!x && days.some(function (c) { return c.h === x; }); };
  // the quiz's planned lesson date comes first, then today
  const def = date || (has(q.lesson_date) ? q.lesson_date : (has(today) ? today : ''));
  const col = days.filter(function (c) { return c.h === def; })[0];
  const filled = col ? d.students.filter(function (s) { return String(s.v[col.c - 1] || '').trim() !== ''; }).length : 0;
  const m = openMap_();
  return { dates: days.map(function (c) { return c.h; }), date: def, today: today, dateOk: !!col, filled: filled, students: d.students.length,
    otherOpen: Object.keys(m).filter(function (k) { return k !== id; }).map(function (k) { return m[k].group; }) };
}

function apiStartQuiz(t, id, minutes, date) {
  requireTeacher_(t);
  closeExpiredQuizzes_();
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const q = getQuiz_(id);
    if (q.status === 'open') throw new Error('This quiz is already open.');
    if (q.status === 'closed') throw new Error('This quiz has already been used. Duplicate it to run it again.');
    const m = openMap_();
    const other = Object.keys(m)[0];
    if (other) throw new Error('Another quiz is open now (group ' + m[other].group + '). Close it first.');
    const min = Math.round(Number(minutes || q.duration_min || 10));
    if (!(min >= 1 && min <= 60)) throw new Error('Time must be 1–60 minutes.');
    if (!/^\d{2}\.\d{2}$/.test(String(date || ''))) date = Utilities.formatDate(new Date(), 'Asia/Tashkent', 'dd.MM');
    const now = Date.now(), closes = new Date(now + min * 60000).toISOString();
    patchQuiz_(id, { status: 'open', opened_at: new Date(now).toISOString(), closes_at: closes, lesson_date: date, duration_min: String(min) });
    m[id] = { group: q.group, closes: closes }; setJprop_('OPEN_QUIZZES', m);
    props_().deleteProperty('QS_' + id);
    log_('teacher', 'quiz-open', q.group + ' | ' + q.title + ' | ' + min + ' min | ' + date);
  } finally { lock.releaseLock(); }
  try { ensureTrigger_(); } catch (e) { log_('system', 'trigger-error', e.message); }
  return apiQuizResults(t, id);
}

function apiExtendQuiz(t, id, minutes) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  if (q.status !== 'open') throw new Error('The quiz is not open.');
  const add = Math.round(Number(minutes || 2));
  if (!(add >= 1 && add <= 30)) throw new Error('Add 1–30 minutes.');
  let closesMs = Math.max(Date.now(), new Date(q.closes_at).getTime()) + add * 60000;
  if (q.opened_at) closesMs = Math.min(closesMs, latestClose_(q.opened_at).getTime());   // never past the end of the next day
  const closes = new Date(closesMs).toISOString();
  patchQuiz_(id, { closes_at: closes });
  const m = openMap_(); if (m[id]) { m[id].closes = closes; setJprop_('OPEN_QUIZZES', m); }
  log_('teacher', 'quiz-extend', q.group + ' | ' + q.title + ' | +' + add);
  return apiQuizResults(t, id);
}

function apiCloseQuiz(t, id) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  if (q.status !== 'open') throw new Error('The quiz is not open.');
  const past = new Date(Date.now() - GRACE_MS - 1000).toISOString();
  patchQuiz_(id, { closes_at: past });
  const m = openMap_(); if (m[id]) { m[id].closes = past; setJprop_('OPEN_QUIZZES', m); }
  finalizeQuiz_(id);
  return apiQuizResults(t, id);
}

function apiNotifyQuiz(t, id) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  if (q.status !== 'open') throw new Error('Start the quiz first.');
  const accs = readTable_('_p_students').filter(function (r) { return r.group === q.group && r.status === 'active' && r.tg_id; });
  let sent = 0;
  accs.forEach(function (a) {
    if (send_(a.tg_id, '📝 <b>Quiz is open:</b> ' + h_(q.title) + '\nOpen your page and press Start.', [[{ text: 'Open quiz', url: studentUrl_(a.token) }]])) sent++;
  });
  log_('teacher', 'quiz-notify', q.group + ' | ' + q.title + ' | ' + sent + '/' + accs.length);
  return { sent: sent, of: accs.length };
}

function apiQuizResults(t, id) {
  requireTeacher_(t);
  const q = refreshQuiz_(getQuiz_(id));
  const d = readGroup_(q.group, false);
  const atts = readTable_('_p_attempts').filter(function (a) { return a.quiz_id === q.quiz_id; });
  const sm = startedMap_(q.quiz_id);
  const col = q.lesson_date ? dayCol_(q.group, q.lesson_date) : null;
  const linked = {};
  readTable_('_p_students').forEach(function (r) { if (r.group === q.group && r.status === 'active') linked[r.full_name] = true; });
  const rows = d.students.map(function (s) {
    const a = atts.filter(function (x) { return x.full_name === s.name; })[0];
    return { row: s.row, name: s.name, linked: !!linked[s.name],
      state: a ? 'done' : (sm[s.name] ? 'working' : 'not started'),
      score10: a ? Number(a.score10) : null, written: a ? a.written_to_sheet === 'yes' : false, note: a ? a.note : '',
      cell: col ? String(s.v[col.c - 1] || '').trim() : null };
  });
  const parsed = atts.map(function (a) { return (JSON.parse(a.answers_json || '{}').r) || {}; });
  const stats = q.questions.map(function (x, i) {
    let n = 0, sum = 0;
    parsed.forEach(function (r) { if (r[x.id] != null) { n++; sum += Number(r[x.id]); } });
    return { n: i + 1, type: x.type, prompt: x.prompt, right: correctText_(x), explain: x.explain, answered: n,
      wrongPct: n ? Math.round((1 - sum / n) * 100) : null };
  });
  const scores = atts.map(function (a) { return Number(a.score10); });
  const top = stats.filter(function (s) { return s.answered && s.wrongPct > 0; })
    .sort(function (a, b) { return b.wrongPct - a.wrongPct; }).slice(0, 4);
  return { quiz: quizMeta_(q, atts), rows: rows, stats: stats, top: top, done: atts.length, students: d.students.length,
    avg: scores.length ? round1_(scores.reduce(function (a, b) { return a + b; }, 0) / scores.length) : null,
    dateOk: !!col, now: nowIso_() };
}

/** One click: 0 (= absent) for students who did not take the quiz (only empty cells). */
function apiQuizMarkNb(t, id, rows) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  const col = q.lesson_date ? dayCol_(q.group, q.lesson_date) : null;
  if (!col) throw new Error('No date column ' + q.lesson_date + ' in group ' + q.group + '.');
  const d = readGroup_(q.group, true);
  const want = (rows || []).map(Number);
  const entries = d.students.filter(function (s) { return want.indexOf(s.row) >= 0 && String(s.v[col.c - 1] || '').trim() === ''; })
    .map(function (s) { return { row: s.row, col: col.c, value: 0 }; });
  if (entries.length) writeCells_(q.group, entries, 'teacher');
  return apiQuizResults(t, id);
}

/** Teacher decides to replace the existing mark with the quiz mark (conflict case). */
function apiQuizUseMark(t, id, name) {
  requireTeacher_(t);
  const q = getQuiz_(id);
  const att = attemptOf_(id, name);
  if (!att) throw new Error('No result for ' + name + '.');
  const col = q.lesson_date ? dayCol_(q.group, q.lesson_date) : null;
  if (!col) throw new Error('No date column ' + q.lesson_date + ' in group ' + q.group + '.');
  const st = readGroup_(q.group, true).students.filter(function (s) { return s.name === name; })[0];
  if (!st) throw new Error('Student not found in the sheet.');
