  const sh = pSheet_('_p_attempts'), H = P_SHEETS._p_attempts;
  sh.getRange(att._row, H.indexOf('written_to_sheet') + 1).setValue('yes');
  sh.getRange(att._row, H.indexOf('note') + 1).setValue((att.note ? att.note + '; ' : '') + 'written by teacher');
  SpreadsheetApp.flush(); tableChanged_('_p_attempts');
  return apiQuizResults(t, id);
}


