/** Reading / writing the gradebook. Columns are always found by header text (row 3). */

const P_SHEETS = {
  _p_settings: ['key', 'value'],
  _p_students: ['group', 'full_name', 'tg_id', 'tg_username', 'token', 'status', 'linked_at'],
  _p_lessons: ['group', 'date', 'unit', 'topic', 'done', 'homework', 'quiz_id', 'notes', 'focus'],
  _p_quizzes: ['quiz_id', 'group', 'unit', 'title', 'duration_min', 'status', 'opened_at', 'closes_at', 'questions_json', 'lesson_date', 'created_at'],
  _p_attempts: ['quiz_id', 'group', 'full_name', 'started_at', 'submitted_at', 'answers_json', 'score_raw', 'score10', 'written_to_sheet', 'note'],
  _p_deadlines: ['id', 'group', 'title', 'due_date', 'type', 'notes'],
  _p_log: ['time', 'actor', 'action', 'details'],
  _p_outbox: ['id', 'group', 'full_name', 'text', 'status', 'created_at', 'sent_at', 'button'],
  _p_personal: ['id', 'group', 'full_name', 'kind', 'title', 'questions_json', 'target_json', 'max_score', 'duration_min', 'deadline', 'show_score', 'status', 'started_at', 'closes_at', 'submitted_at', 'answers_json', 'score_raw', 'score', 'written', 'note', 'created_at'],
  _p_live: ['time', 'quiz_id', 'group', 'title', 'lesson_date', 'name', 'nick', 'kind', 'right', 'total', 'points', 'rank', 'mark', 'note'],
  _p_groups: ['group', 'subject', 'chat_id', 'chat_title', 'status', 'created_at'],
  _p_archive: ['id', 'group', 'full_name', 'removed_at', 'data_json', 'status']
};
const HEADER_ROW = 3;
const FIRST_STUDENT_ROW = 4;
const NAME_COL = 2;

function pSheet_(name) {
  const ss = ss_();
  let sh = ss.getSheetByName(name);
  if (!sh) {
    sh = ss.insertSheet(name, ss.getNumSheets());
    sh.getRange(1, 1, 1, P_SHEETS[name].length).setValues([P_SHEETS[name]]).setFontWeight('bold');
    sh.setFrozenRows(1);
    // keep plain text so "07.11" stays a string
    sh.getRange('A:Z').setNumberFormat('@');
    sh.hideSheet();
  }
  return sh;
}

function ensureSheets_() {
  const sig = JSON.stringify(P_SHEETS);
  if (props_().getProperty('SCHEMA_OK') === sig) return;
  Object.keys(P_SHEETS).forEach(function (n) {
    const sh = pSheet_(n), want = P_SHEETS[n];
    if (sh.getMaxColumns() < want.length) sh.insertColumnsAfter(sh.getMaxColumns(), want.length - sh.getMaxColumns());
    const have = sh.getRange(1, 1, 1, want.length).getDisplayValues()[0];
    want.forEach(function (h, i) { if (!have[i]) sh.getRange(1, i + 1).setValue(h).setFontWeight('bold'); });
  });
  props_().setProperty('SCHEMA_OK', sig);
}

/** Groups = sheets listed in _p_groups (not archived) + TEST. Before _p_groups is filled: the 3-digit sheets. */
function listGroups_() {
  const names = ss_().getSheets().map(function (s) { return s.getName(); });
  const meta = groupsMeta_(), any = Object.keys(meta).length > 0;
  return names.filter(function (n) {
    if (n === 'TEST') return true;
    return any ? !!(meta[n] && meta[n].status !== 'archived') : /^\d{3}$/.test(n);
  });
}

function classify_(h) {
  if (/^\d{2}\.\d{2}$/.test(h)) return { kind: 'day', max: 10 };
  if (h === 'Oraliq N (20)') return { kind: 'manual', max: 20 };
  if (/^PW[12] \(5\)$/.test(h)) return { kind: 'manual', max: 5 };
  if (/^PW[12] jamoasi/.test(h)) return { kind: 'team' };
  if (/^MT\d+ \(1\)$/.test(h)) return { kind: 'manual', max: 1 };
  if (h === 'YN (50)') return { kind: 'manual', max: 50 };
  if (h === '№' || h === 'F.I.Sh.') return { kind: 'id' };
  if (!h) return { kind: 'empty' };
  return { kind: 'formula' };
}

function groupSheet_(g) {
  if (listGroups_().indexOf(String(g)) < 0) throw new Error('Unknown group: ' + g);
  return ss_().getSheetByName(String(g));
}

/** Full group snapshot: header info + every student row (display values). */
function readGroup_(g, fresh) {
  const cache = CacheService.getScriptCache();
  const key = 'grp_' + g;
  if (!fresh) {
    const hit = cache.get(key);
    if (hit) return JSON.parse(hit);
  }
  const sh = groupSheet_(g);
  const lr = sh.getLastRow(), lc = sh.getLastColumn();
  const disp = sh.getRange(1, 1, lr, lc).getDisplayValues();
  const nData = Math.max(1, lr - HEADER_ROW);
  const formulas = sh.getRange(FIRST_STUDENT_ROW, 1, nData, lc).getFormulas();
  const row2 = disp[1], hdr = disp[2];
  const cols = [];
  let section = '';
  for (let c = 0; c < lc; c++) {
    let h = String(hdr[c] || '').trim();
    // a date typed by hand may show as "5.11" (number) — read it as "05.11"
    const dm = /^(\d{1,2})\.(\d{1,2})$/.exec(h);
    if (dm && +dm[1] >= 1 && +dm[1] <= 31 && +dm[2] >= 1 && +dm[2] <= 12) h = ('0' + dm[1]).slice(-2) + '.' + ('0' + dm[2]).slice(-2);
    if (String(row2[c] || '').trim()) section = String(row2[c]).trim();
    let cl = classify_(h);
    if (cl.kind === 'day' || cl.kind === 'manual' || cl.kind === 'team') {
      for (let r = 0; r < formulas.length; r++) if (formulas[r][c]) { cl = { kind: 'formula' }; break; }
    }
    const block = /^1-/.test(section) ? 1 : /^2-/.test(section) ? 2 : 0;
    cols.push({ c: c + 1, h: h, kind: cl.kind, max: cl.max || null, block: block, section: section });
  }
  const students = [];
  for (let r = FIRST_STUDENT_ROW - 1; r < lr; r++) {
    const name = String(disp[r][NAME_COL - 1] || '').trim();
    if (!name) continue;
    students.push({ row: r + 1, no: disp[r][0], name: name, v: disp[r] });
  }
  const data = { group: String(g), title: disp[0][0], cols: cols, students: students };
  try { cache.put(key, JSON.stringify(data), 60); } catch (e) { /* too big for cache: fine */ }
  return data;
}

/** A daily mark that means "absent": 0 (since 10.11.2026) or the old "nb". */
function isAbsent_(raw) {
  const v = String(raw == null ? '' : raw).trim().toLowerCase();
  return v === 'nb' || (v !== '' && Number(v.replace(',', '.')) === 0);
}

function clearGroupCache_(g) { CacheService.getScriptCache().remove('grp_' + g); }

/** Validates a value for a column. Returns {value} to write ('' clears). */
function normalize_(col, raw) {
  const v = String(raw == null ? '' : raw).trim();
  if (v === '') return { value: '' };
  if (col.kind === 'team') {
    if (v.length > 30) throw new Error('Team name is too long.');
    return { value: v };
  }
  // absent = 0 (Valisher, 10.11.2026): "nb" typed by hand is written as 0
  if (col.kind === 'day' && v.toLowerCase() === 'nb') return { value: 0 };
  const n = Number(v.replace(',', '.'));
  if (!isFinite(n) || n < 0 || n > col.max) {
    throw new Error('"' + v + '" is not allowed in ' + col.h + '. Use 0–' + col.max + (col.kind === 'day' ? ' (0 = absent)' : '') + '.');
  }
  return { value: Math.round(n * 100) / 100 };
}

/**
 * Writes a batch of cells in one group under the script lock.
 * entries: [{row, col, value}]. Returns fresh display rows for touched students.
 */
function writeCells_(g, entries, actor) {
  const lock = LockService.getScriptLock();
  lock.waitLock(20000);
  try {
    const data = readGroup_(g, true);
    const sh = groupSheet_(g);
    const rowsOk = {};
    data.students.forEach(function (s) { rowsOk[s.row] = s.name; });
    const prepared = entries.map(function (e) {
      const row = Number(e.row), colNo = Number(e.col);
      const col = data.cols[colNo - 1];
      if (!rowsOk[row]) throw new Error('Row ' + row + ' is not a student row.');
      if (!col || ['day', 'manual', 'team'].indexOf(col.kind) < 0) throw new Error('Column "' + (col ? col.h : colNo) + '" cannot be edited.');
      return { row: row, col: col, name: rowsOk[row], val: normalize_(col, e.value).value };
    });
    prepared.forEach(function (p) {
      const cell = sh.getRange(p.row, p.col.c);
      if (cell.getFormula()) throw new Error('Formula cell, not edited: ' + p.col.h);
      const old = cell.getDisplayValue();
      if (String(old) === String(p.val)) return;
      if (p.val === '') cell.clearContent(); else cell.setValue(p.val);
      log_(actor, 'set', g + ' | ' + p.name + ' | ' + p.col.h + ' | ' + old + ' -> ' + p.val);
    });
    SpreadsheetApp.flush();
    clearGroupCache_(g);
    const lc = sh.getLastColumn();
    const out = {};
    prepared.forEach(function (p) {
      if (!out[p.row]) out[p.row] = sh.getRange(p.row, 1, 1, lc).getDisplayValues()[0];
    });
    return out;
  } finally {
    lock.releaseLock();
  }
}

/* ---------- small table helpers for _p_ sheets ---------- */

/* ---------- cached reads for the busy pages (students, Today, Lessons) ----------
 * readTable_ is always fresh (used before every write). readTableC_ keeps a copy in CacheService.
 * Every write bumps the table version (Script Property TV_<name>), so a cached copy is never older
 * than the last write made by this script. Manual edits in the sheet show up within TABLE_TTL seconds. */
const TABLE_TTL = 120;
function tableVer_(name) { return props_().getProperty('TV_' + name) || '0'; }
function tableChanged_(name) { try { props_().setProperty('TV_' + name, String(Date.now())); } catch (e) { /* ignore */ } }
function readTableC_(name) {
  const key = 'tb_' + name + '_' + tableVer_(name);
  const hit = cacheGetBig_(key);
  if (hit) { try { return JSON.parse(hit); } catch (e) { /* rebuild */ } }
  const rows = readTable_(name);
  cachePutBig_(key, JSON.stringify(rows), TABLE_TTL);
  return rows;
}
/** CacheService values are limited to 100 KB: big strings are gzipped and split into parts. */
function cachePutBig_(key, s, ttl) {
  try {
    const c = CacheService.getScriptCache();
    let z = s, gz = 0;
    if (s.length > 30000) { z = Utilities.base64Encode(Utilities.gzip(Utilities.newBlob(s, 'application/json')).getBytes()); gz = 1; }
    const parts = [];
    for (let i = 0; i < z.length; i += 90000) parts.push(z.slice(i, i + 90000));
    if (parts.length > 25) return;
    const o = {};
    parts.forEach(function (p, i) { o[key + '_' + i] = p; });
    o[key] = JSON.stringify({ n: parts.length, gz: gz });
    c.putAll(o, ttl);
  } catch (e) { /* cache is optional */ }
}
function cacheGetBig_(key) {
  try {
    const c = CacheService.getScriptCache();
    const h = c.get(key); if (!h) return null;
    const m = JSON.parse(h), ks = [];
    for (let i = 0; i < m.n; i++) ks.push(key + '_' + i);
    const got = c.getAll(ks);
    let z = '';
    for (let i = 0; i < m.n; i++) { if (got[ks[i]] == null) return null; z += got[ks[i]]; }
    return m.gz ? Utilities.ungzip(Utilities.newBlob(Utilities.base64Decode(z), 'application/x-gzip')).getDataAsString('UTF-8') : z;
  } catch (e) { return null; }
}

function readTable_(name) {
  const sh = pSheet_(name);
  const vals = sh.getDataRange().getDisplayValues();
  const head = vals[0];
  return vals.slice(1).map(function (r, i) {
    const o = { _row: i + 2 };
    head.forEach(function (h, j) { o[h] = r[j]; });
    return o;
  });
}

function upsertRow_(name, matchFn, obj) {
  const sh = pSheet_(name);
  const head = P_SHEETS[name];
  const rows = readTable_(name);
  const hit = rows.filter(matchFn)[0];
  const line = head.map(function (h) { return obj[h] == null ? (hit ? hit[h] : '') : String(obj[h]); });
  // plain text, so "08.11" or a hex token never turns into a number
  const r = hit ? hit._row : sh.getLastRow() + 1;
  sh.getRange(r, 1, 1, head.length).setNumberFormat('@').setValues([line]);
  SpreadsheetApp.flush(); // so a parallel run (bot tick) never reads a stale table and appends a duplicate
  tableChanged_(name);
}

// patch one exact row (by _row), not "the first row that matches"
function patchRowAt_(name, rowObj, patch) {
  const sh = pSheet_(name);
  const head = P_SHEETS[name];
  const line = head.map(function (h) { return patch[h] == null ? (rowObj[h] == null ? '' : rowObj[h]) : String(patch[h]); });
  sh.getRange(rowObj._row, 1, 1, head.length).setNumberFormat('@').setValues([line]);
  SpreadsheetApp.flush();
  tableChanged_(name);
}

/**
 * Student API (site page s.html). The key is the student's personal token from _p_students.
 * A student only ever gets their own row, anonymous group numbers and their own quiz results.
 */
const ST_ACTIONS = {
  stHome: stHome, stPing: stPing,
  stQuizStart: stQuizStart, stQuizSave: stQuizSave, stQuizSubmit: stQuizSubmit, stQuizReview: stQuizReview, stLiveJoin: stLiveJoin,
  stPractice: stPractice, stPracticeCheck: stPracticeCheck
};

function studentByToken_(k) {
  k = String(k || '');
  if (!/^[a-f0-9]{40}$/.test(k)) return null;
  const cache = CacheService.getScriptCache();
  const hit = cache.get('stu_' + k);
  if (hit) return JSON.parse(hit);
  const r = readTable_('_p_students').filter(function (x) { return x.token === k && x.status === 'active'; })[0];
  if (!r) return null;
  const me = { group: r.group, name: r.full_name, token: k };
  cache.put('stu_' + k, JSON.stringify(me), 300);
  return me;
}

function round1_(x) { return Math.round(x * 10) / 10; }

/** Daily-mark statistics for one student row (numbers computed here, never guessed). */
function markStats_(d, st) {
  let sum = 0, cnt = 0, nb = 0, attended = 0;
  const series = [];
  d.cols.forEach(function (c) {
    if (c.kind !== 'day') return;
    const raw = String(st.v[c.c - 1] || '').trim();
    let val = null;
    if (isAbsent_(raw)) nb++;
    if (raw.toLowerCase() === 'nb') { /* old absent mark */ }
    else if (raw !== '') { const n = Number(raw.replace(',', '.')); if (isFinite(n)) { val = n; sum += n; cnt++; if (n !== 0) attended++; } }
    series.push({ date: c.h, block: c.block, raw: raw, val: val, absent: isAbsent_(raw) });
  });
  // average: like the gradebook, 0 (absent) counts; attended = lessons with a mark above 0
  return { series: series, avg: cnt ? round1_(sum / cnt) : null, attended: attended, nb: nb, marked: attended + nb, sum: sum, cnt: cnt };
}

function studentSummary_(g, name) {
  const d = readGroup_(g, false);
  const st = d.students.filter(function (s) { return s.name === name; })[0];
  if (!st) throw new Error('Your name is not in the gradebook of group ' + g + '. Please tell your teacher.');
  const me = markStats_(d, st);
  let gs = 0, gc = 0;
  const avgs = d.students.map(function (s) {
    const m = markStats_(d, s); gs += m.sum; gc += m.cnt; return m.avg;
  }).filter(function (a) { return a != null; });
  me.groupAvg = gc ? round1_(gs / gc) : null;
  me.rank = me.avg == null ? null : 1 + avgs.filter(function (a) { return a > me.avg; }).length;
  me.ranked = avgs.length;
  me.last = me.series.filter(function (x) { return x.raw !== ''; }).slice(-3);
  me.d = d; me.st = st;
  return me;
}

function stHome(me) {
  const s = studentSummary_(me.group, me.name);
  const cell = function (h, i) {
    const cs = s.d.cols.filter(function (c) { return c.h === h; });
    return cs[i || 0] ? String(s.st.v[cs[i || 0].c - 1] || '') : '';
  };
  const totals = [['Current mark · block 1', cell('Joriy (20)', 0), 20], ['Rating 1', cell('1-reyting (20)'), 20],
    ['Current mark · block 2', cell('Joriy (20)', 1), 20], ['Rating 2', cell('2-reyting (20)'), 20],
    ['Independent work', cell('MI (10)'), 10], ['Total', cell('Jami (100)'), 100]]
    .map(function (x) { return { label: x[0], value: x[1], max: x[2] }; });
  // Teacher can hold back ratings/total (e.g. midterm entered but not announced): _p_settings hide_totals = "109,209"
  const hidG = String(getSetting_('hide_totals', '') || '').split(/[,\s]+/);
  if (hidG.indexOf(String(me.group)) >= 0) totals.forEach(function (t) { if (/^(Rating|Total)/.test(t.label)) t.value = ''; });
  const today = Utilities.formatDate(new Date(), 'Asia/Tashkent', 'dd.MM');
  const saved = {};
  readTableC_('_p_lessons').forEach(function (r) { if (r.group === me.group) saved[r.date] = r; });
  let lessons = s.d.cols.filter(function (c) { return c.kind === 'day'; }).map(function (c, i) {
    const l = saved[c.h] || {};
    return { n: i + 1, date: c.h, unit: l.unit || '', topic: l.topic || '', homework: l.homework || '' };
  }).filter(function (l) { return l.topic || l.homework; });
  // past lessons + the next two (so students see what is coming)
  const upNext = lessons.filter(function (l) { return ddmm_(l.date) > ddmm_(today); }).slice(0, 2);
  lessons = lessons.filter(function (l) { return ddmm_(l.date) <= ddmm_(today); }).concat(upNext);
  const now = new Date();
  const base = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const deadlines = readTableC_('_p_deadlines').filter(function (r) { return r.group === me.group || r.group === 'all'; })
    .map(function (r) {
      const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(r.due_date);
      return { title: r.title, due_date: r.due_date, type: r.type, notes: r.notes,
        days: m ? Math.round((new Date(+m[3], +m[2] - 1, +m[1]) - base) / 864e5) : null };
    }).filter(function (r) { return r.days != null && r.days >= -1; })
    .sort(function (a, b) { return a.days - b.days; });
  const oq = openQuizFor_(me.group);
  let quiz = null;
  if (oq) {
    const att = attemptOf_(oq.quiz_id, me.name);
    quiz = { quiz_id: oq.quiz_id, title: oq.title, unit: oq.unit, closes_at: oq.closes_at, count: oq.questions.length,
      state: att ? 'done' : (startedMap_(oq.quiz_id)[me.name] ? 'working' : 'new'), score10: att ? Number(att.score10) : null };
  }
  return {
    name: me.name, group: me.group, subject: subjectOf_(me.group), teacher: teacherName_(), fb: fbConfig_(), today: today, now: new Date().toISOString(),
    avg: s.avg, groupAvg: s.groupAvg, rank: s.rank, ranked: s.ranked, attended: s.attended, nb: s.nb, marked: s.marked,
    series: s.series.filter(function (x) { return x.raw !== '' || ddmm_(x.date) <= ddmm_(today); }),
    totals: totals, lessons: lessons, deadlines: deadlines, quiz: quiz, personal: (function () { try { return personalFor_(me); } catch (e) { return []; } })(), results: quizHistory_(me.group, me.name),
    live: (function () { const L = liveFor_(me.group); if (!L) return null; let t = ''; try { t = getQuiz_(L.quiz_id).title; } catch (e) {} return { gid: L.gid, title: t }; })()
  };
}

/** Light call the page repeats every 15 s to notice a quiz opening. */
function stPing(me) {
  const m = openMap_();
  const id = Object.keys(m).filter(function (k) { return m[k].group === me.group; })[0];
  const L = liveFor_(me.group);
  return { open: id || null, closes: id ? m[id].closes : null, live: L ? L.gid : null };
}

/** A student's quiz attempts (used on the student page and the teacher's profile view). */
function quizHistory_(g, name) {
  const quizzes = {};
  quizRowsC_().forEach(function (q) { if (q.group === String(g)) quizzes[q.quiz_id] = q; });
  const atts = readTableC_('_p_attempts').filter(function (a) { return a.group === String(g) && a.full_name === name; });
  const out = atts.map(function (a) {
    const q = quizzes[a.quiz_id] || {};
    const r = (JSON.parse(a.answers_json || '{}').r) || {};
    const ids = Object.keys(r);
    return { quiz_id: a.quiz_id, title: q.title || '(deleted quiz)', unit: q.unit || '', date: q.lesson_date || '',
      score10: Number(a.score10), right: ids.filter(function (k) { return r[k] >= 1; }).length, total: ids.length,
      reviewable: q.status === 'closed', note: a.note || '' };
  });
  Object.keys(quizzes).forEach(function (id) {
    const q = quizzes[id];
    if (q.status === 'closed' && !atts.some(function (a) { return a.quiz_id === id; }))
      out.push({ quiz_id: id, title: q.title, unit: q.unit, date: q.lesson_date || '', score10: null, missed: true });
  });
  return out.sort(function (a, b) { return ddmm_(b.date) - ddmm_(a.date); });
}

/** Lesson plan seed: unit + topic + focus for every gradebook date (from the fan dasturi / Teacher's Books).
 * Written once into _p_lessons (only empty fields are filled; rows marked force get the right unit/topic).
 * 106/109/209: lesson N = Unit N. 107: 05.11 (header "5.11") = Unit 15, 09.11 = Unit 16 ...
 * 223: gradebook lesson k = HEMIS topic k+1 (30.10 = 5.1 Journeys). */
const LESSON_SEED_VERSION = '2026-11-09a';
const LESSON_SEED = [];

function seedLessons_() {
  if (!IS_MAIN || !LESSON_SEED.length) return false;   // Valisher's own topics only
  if (props_().getProperty('LESSONS_SEED') === LESSON_SEED_VERSION) return false;
  if (getSetting_('lessons_seed', '') === LESSON_SEED_VERSION) { props_().setProperty('LESSONS_SEED', LESSON_SEED_VERSION); return false; }
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    if (getSetting_('lessons_seed', '') === LESSON_SEED_VERSION) return false;
    ensureSheets_();
    const sh = pSheet_('_p_lessons'), head = P_SHEETS._p_lessons;
    const rows = readTable_('_p_lessons');
    const lines = rows.map(function (r) { return head.map(function (h) { return r[h] == null ? '' : String(r[h]); }); });
    const idx = {};
    rows.forEach(function (r, i) { idx[r.group + '|' + r.date] = i; });
    const col = {}; head.forEach(function (h, i) { col[h] = i; });
    let added = 0, filled = 0;
    LESSON_SEED.forEach(function (s) {
      const k = s.g + '|' + s.d;
      if (idx[k] == null) {
        const line = head.map(function () { return ''; });
        line[col.group] = s.g; line[col.date] = s.d; line[col.unit] = s.u; line[col.topic] = s.t; line[col.focus] = s.f;
        if (s.xdone) line[col.done] = s.xdone; if (s.xhomework) line[col.homework] = s.xhomework;
        idx[k] = lines.length; lines.push(line); added++;
        return;
      }
      const line = lines[idx[k]];
      if (s.force) { line[col.unit] = s.u; line[col.topic] = s.t; if (s.xdone) line[col.done] = s.xdone; if (s.xhomework) line[col.homework] = s.xhomework; }
      if (!line[col.unit]) line[col.unit] = s.u;
      if (!line[col.topic]) line[col.topic] = s.t;
      if (!line[col.focus]) line[col.focus] = s.f;
      filled++;
    });
    if (lines.length) sh.getRange(2, 1, lines.length, head.length).setNumberFormat('@').setValues(lines);
    SpreadsheetApp.flush();
    tableChanged_('_p_lessons');
    setSetting_('lessons_seed', LESSON_SEED_VERSION);
    props_().setProperty('LESSONS_SEED', LESSON_SEED_VERSION);
    log_('system', 'lessons-seed', LESSON_SEED_VERSION + ' added ' + added + ', updated ' + filled);
    return true;
  } finally { lock.releaseLock(); }
}
